const unpack=(fields,row)=>Object.fromEntries(fields.map((k,i)=>[k,row[i]]));

/* ---------- the archive ---------- */
const PLAYERS=A.players; const pname=id=>PLAYERS[id]?.n||id; const pnames=ids=>(ids||[]).map(pname).join(' / ');
const TOURN=Object.fromEntries(Object.entries(A.tournaments).map(([id,r])=>[id,{id,...unpack(A.tFields,r)}]));
const EDS=Object.fromEntries(Object.entries(A.editions).map(([id,r])=>{const e={id,...unpack(A.eFields,r)};e.team=!!e.team;if(!e.name)e.name=TOURN[e.t]?.n||e.id;return [id,e];}));
const CHAMPS=A.champions.map(r=>unpack(A.cFields,r));
const PS=A.ps.map(r=>unpack(A.psFields,r));
const RIVALS=A.rivals||{}, RECORDS=A.records||{}, IOC=A.ioc||{}, RIVER=A.river||{}, TITLESBY=A.titlesBy||{};
const MF=['id','w','l','s','r','n','mins','bo','ws','ls','wr','lr','st','src'];
const MAJORS=Object.values(TOURN).filter(t=>t.major).map(t=>t.id);
const natName=c=>IOC[c]||c||'Unlisted';
const SURF={Hard:'#3b82f6',Clay:'#d2622b',Grass:'#4caf50',Carpet:'#8b7bb5',Unknown:'#737d8c'};
const surfColor=s=>SURF[s]||SURF.Unknown;
const LEVEL={G:'Grand Slam',M:'Masters 1000',PM:'Premier Mandatory',P:'Premier',I:'International',W:'WTA Tour',A:'Tour',T1:'Tier I',T2:'Tier II',T3:'Tier III',T4:'Tier IV',T5:'Tier V',F:'Tour Finals',D:'Team competition',CC:'Team cup',O:'Olympic Games',E:'Exhibition',J:'Junior','50+H':'Senior','35+H':'Senior'};
const levelName=l=>LEVEL[l]||l;
const LEVEL_RANK={G:6,F:5,O:5,M:4,PM:4,P:3,T1:3,T2:2,W:2,A:2,I:2,T3:1,T4:1,T5:1,CC:1,D:1,E:0,J:0};

/* ---------- nations: colours ---------- */
const NAT_COL={'':'#4b5058',UNK:'#4b5058',USA:'#d62839',AUS:'#ffcc00',GBR:'#2c4ec7',FRA:'#7aa6ff',ESP:'#ff8c1a',GER:'#c9ccd1',FRG:'#c9ccd1',SWE:'#3ec6b8',ARG:'#9dd2f2',CZE:'#7b3fa0',TCH:'#7b3fa0',SUI:'#ff2e63',ITA:'#3aaa5c',RUS:'#c81e6e',URS:'#c81e6e',SRB:'#e8967a',BEL:'#b58900',NED:'#ff9e80',CRO:'#a8dadc',ROU:'#c5a3ff',POL:'#ff7b7b',JPN:'#f4f4f2',CAN:'#ff8a80',BRA:'#a4ff4f',CHN:'#ff5a36',RSA:'#0f9d58',NZL:'#9e9e9e',DEN:'#e57373',AUT:'#f06292',BLR:'#4db6ac',UKR:'#ffe082',KAZ:'#80deea',GRE:'#64b5f6',NOR:'#5c6bc0',CHI:'#ef9a9a',ECU:'#fff176',YUG:'#ba68c8',SVK:'#4dd0e1',BUL:'#aed581',SLO:'#90caf9',LAT:'#bf360c',TUN:'#d4e157',IND:'#ffab40',MEX:'#66bb6a',HUN:'#8d6e63',FIN:'#b3e5fc',ISR:'#42a5f5',ZIM:'#ffca28',TPE:'#26a69a',KOR:'#7e57c2',THA:'#ab47bc',EGY:'#ff7043',PER:'#ec407a',URU:'#29b6f6',COL:'#fdd835',VEN:'#ffee58',PAR:'#d81b60',MAR:'#c62828',POR:'#2e7d32'};
const hueCache={};
const natColor=c=>{if(NAT_COL[c])return NAT_COL[c];if(hueCache[c])return hueCache[c];let h=0;for(const ch of String(c||'?'))h=(h*31+ch.charCodeAt(0))>>>0;return hueCache[c]=hsl2hex(h%360,45,62);};
const color=natColor;
const teamVar=c=>`--team:${natColor(c)}`;
const pnat=id=>PLAYERS[id]?.ioc||'';
const pcolor=id=>natColor(pnat(id));

/* ---------- lens: tour + draw (the masthead selects), then era + season as everywhere ---------- */
const state={tour:'M',disc:'S',era:'all',year:null,tab:'season',edition:null,match:null,nation:null,player:null,tourn:null,lens:'t',plens:'t',heat:'t',duelBy:'p',dA:null,dB:null,gridSort:'count',gridFind:'',gridMin:10,focusTeam:null,whole:false,find2:'',bracketRound:null};
const circs=()=>(state.tour==='all'?['M','W']:[state.tour]).map(t=>t+state.disc);
const inLens=c=>circs().includes(c);
const tourLabel=()=>state.tour==='M'?'ATP':state.tour==='W'?'WTA':'ATP & WTA';
const lensLabel=()=>`${tourLabel()} · ${state.disc==='S'?'singles':'doubles'}`;

/* seasons: every year with a title or an edition in the lens */
let S=[],byYear={},FIRST_YEAR=0,LAST_YEAR=0;
function rebuildSeasons(){const map={};const get=y=>map[y]||(map[y]={year:y,editions:[],titles:[],matches:0});
  for(const e of Object.values(EDS)){if(!inLens(e.c))continue;const s=get(e.y);s.editions.push(e);s.matches+=e.n||0;}
  for(const c of CHAMPS){if(!inLens(c.c))continue;get(c.y).titles.push(c);}
  S=Object.keys(map).map(Number).sort((a,b)=>a-b).map(y=>map[y]);for(const s of S){s.editions.sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:0);s.titles.sort((a,b)=>(EDS[a.id]?.date||a.y+'-00')<(EDS[b.id]?.date||b.y+'-00')?-1:1);}
  byYear=Object.fromEntries(S.map(s=>[s.year,s]));FIRST_YEAR=S[0]?.year||1877;LAST_YEAR=S[S.length-1]?.year||2026;seasonBest={};riverModel=null;aggCache={};if(!byYear[state.year])state.year=LAST_YEAR;}
const ERAS=[["lawn","The lawn-tennis age",1877,1913,"Wimbledon from 1877, the US Championships from 1881, the Renshaw and Doherty brothers, the first Davis Cup in 1900; a game of amateurs on grass."],
["musketeers","Lenglen, Tilden and the Musketeers",1914,1945,"Suzanne Lenglen and Bill Tilden, the Four Musketeers at Roland-Garros, Helen Wills Moody, and Don Budge’s first Grand Slam in 1938."],
["amateur","The last amateur years",1946,1967,"Australia’s Davis Cup dynasty under Harry Hopman, Maureen Connolly’s Slam of 1953, Laver’s first in 1962; the professionals barred from the majors until 1968."],
["open","The Open era",1968,1984,"Professionals admitted from Roland-Garros 1968; Laver’s second Slam, Court, King and the founding of the WTA in 1973; Borg, Connors, Evert and Navrátilová; the tie-break and the last wooden racquets."],
["power","The power game",1985,1994,"Becker at seventeen, Lendl, Edberg, Graf’s Golden Slam of 1988 and Seles; graphite, carpet and the indoor season."],
["sampras","Sampras, Agassi and the Williams sisters",1995,2003,"Sampras’s fourteen majors, Agassi’s career Slam, Hingis, and the arrival of Venus and Serena Williams; the ATP Masters Series from 1990 comes of age."],
["big","The Big Three and Serena",2004,2015,"Federer, Nadal and Djokovic take almost every major between them; Serena Williams’s second act; Hawk-Eye from 2006 and the rise of hard courts."],
["reign","The long reign",2016,2021,"Djokovic and Nadal past twenty majors, Federer’s late Wimbledons, Osaka, Barty and Świątek; a tie-break in every final set from 2019."],
["new","The new generation",2022,2026,"Alcaraz and Sinner, Świątek and Sabalenka; the ten-point tie-break at 6–6 in the fifth at every major; the tour after the Big Three."]].map(e=>({id:e[0],name:e[1],from:e[2],to:e[3],text:e[4]}));
const ERA_SHORT={lawn:'Lawn-tennis age',musketeers:'Lenglen, Tilden, Musketeers',amateur:'Last amateur years',open:'Open era',power:'Power game',sampras:'Sampras, Agassi, Williams',big:'Big Three, Serena',reign:'Long reign',new:'New generation'};
const ERA_TINY={lawn:'Lawn',musketeers:'Musketeers',amateur:'Amateur',open:'Open era',power:'Power',sampras:'Sampras',big:'Big Three',reign:'Reign',new:'New'};
const ERA_CHIPS={lawn:['Wimbledon 1877','US Championships 1881','Davis Cup 1900'],musketeers:['Lenglen, Tilden','Roland-Garros 1925','First Grand Slam 1938'],amateur:['Hopman’s Australia','Connolly’s Slam 1953','Amateurs only'],open:['Open tennis 1968','WTA founded 1973','The tie-break'],power:['Becker 1985','Golden Slam 1988','Graphite and carpet'],sampras:['Sampras 14 majors','Masters Series','Williams sisters'],big:['Federer, Nadal, Djokovic','Serena’s second act','Hawk-Eye 2006'],reign:['Twenty majors','Final-set tie-breaks','Osaka, Barty, Świątek'],new:['Alcaraz, Sinner','Świątek, Sabalenka','Ten-point tie-break']};
for(const e of ERAS)e.ball={label:'The game of the era',features:ERA_CHIPS[e.id],svg:ballSvg(e)};
function ballSvg(e){return `<svg viewBox="0 0 300 150" aria-hidden="true"><g transform="translate(90 78) rotate(-35)"><ellipse rx="40" ry="50" fill="none" stroke="#cfd3da" stroke-width="5"/><g stroke="#3a3f48" stroke-width="1.2"><path d="M-30-30v60M-18-42v84M-6-48v96M6-48v96M18-42v84M30-30v60M-38-24h76M-40-12h80M-40 0h80M-40 12h80M-38 24h76"/></g><path d="M-8 50l-6 58h28l-6-58z" fill="#cfd3da"/></g><g transform="translate(215 80)"><circle r="34" fill="var(--accent)" opacity=".92"/><path d="M-30-16c18-8 42-2 46 20M30 16c-18 8-42 2-46-20" fill="none" stroke="#07080a" stroke-width="2.5" opacity=".55"/></g><line x1="10" y1="140" x2="290" y2="140" stroke="#2e333d" stroke-width="2"/><text x="150" y="30" text-anchor="middle" font-family="JetBrains Mono,monospace" font-size="10" letter-spacing="2" fill="#8b9099">${e.from}–${e.to}</text></svg>`;}
const eraOf=y=>ERAS.find(e=>y>=e.from&&y<=e.to)||ERAS[ERAS.length-1];
const eraRange=()=>state.era==='all'?[FIRST_YEAR,LAST_YEAR]:(e=>[e.from,e.to])(ERAS.find(e=>e.id===state.era));
const inEraYear=y=>{const [a,b]=eraRange();return y>=a&&y<=b;};
const eraSeasons=()=>S.filter(s=>inEraYear(s.year));
const eraTitles=()=>eraSeasons().flatMap(s=>s.titles);
const eraEditions=()=>eraSeasons().flatMap(s=>s.editions);
const eraLabel=()=>(state.era==='all'?`All eras · ${FIRST_YEAR}–${LAST_YEAR}`:(e=>`${e.name} · ${e.from}–${e.to}`)(ERAS.find(e=>e.id===state.era)))+' · '+lensLabel();

/* ---------- aggregates from the player-season rows ---------- */
let aggCache={};
function psRows(){const key='ps|'+circs().join()+'|'+state.era;if(aggCache[key])return aggCache[key];const [y0,y1]=eraRange();return aggCache[key]=PS.filter(r=>inLens(r.c)&&r.y>=y0&&r.y<=y1);}
function playerAgg(){const key='pa|'+circs().join()+'|'+state.era;if(aggCache[key])return aggCache[key];const map={};
  for(const r of psRows()){let a=map[r.p]||(map[r.p]={id:r.p,w:0,l:0,t:0,f:0,mj:0,hw:0,hl:0,cw:0,cl:0,gw:0,gl:0,iw:0,il:0,first:r.y,last:r.y,years:0,best:0,bestY:null});for(const k of ['w','l','t','f','mj','hw','hl','cw','cl','gw','gl','iw','il'])a[k]+=r[k]||0;a.first=Math.min(a.first,r.y);a.last=Math.max(a.last,r.y);a.years++;if(r.t>a.best||(r.t===a.best&&r.w>0&&a.bestY==null)){a.best=r.t;a.bestY=r.y;}}
  const out=Object.values(map).map(a=>({...a,p:a.w+a.l,rate:pct(a.w,a.w+a.l),nat:pnat(a.id),name:pname(a.id)}));return aggCache[key]=out;}
function natAgg(){const key='na|'+circs().join()+'|'+state.era;if(aggCache[key])return aggCache[key];const map={};
  for(const r of psRows()){const c=pnat(r.p);let a=map[c]||(map[c]={id:c,w:0,l:0,t:0,f:0,mj:0,players:new Set(),first:r.y,last:r.y,winners:new Set()});a.w+=r.w;a.l+=r.l;a.t+=r.t;a.f+=r.f;a.mj+=r.mj;a.players.add(r.p);if(r.t)a.winners.add(r.p);a.first=Math.min(a.first,r.y);a.last=Math.max(a.last,r.y);}
  const out=Object.values(map).map(a=>({...a,name:natName(a.id),p:a.w+a.l,rate:pct(a.w,a.w+a.l),np:a.players.size,nw:a.winners.size}));return aggCache[key]=out;}
const LENSES={t:['Titles','Tour-level titles won by the nation’s players in the lens.'],mj:['Majors','Grand Slam titles.'],w:['Match wins','Matches won by the nation’s players (from 1968).'],rate:['Win rate %','Wins divided by matches played. Minimum 200 matches.'],np:['Players','Players who appeared in the lens.'],nw:['Title winners','Different players who won a title.']};
const PLENSES={t:['Titles','Tour-level titles in the lens.'],mj:['Majors','Grand Slam titles.'],f:['Finals','Finals reached, won or lost.'],w:['Match wins','Matches won (results recorded from 1968).'],rate:['Win rate %','Wins divided by matches played. Minimum 100 matches.'],cw:['Clay wins','Match wins on clay.'],gw:['Grass wins','Match wins on grass.'],hw:['Hard-court wins','Match wins on hard courts.']};
const playerOrder=(a,b)=>b.t-a.t||b.mj-a.mj||b.f-a.f||b.w-a.w;
let seasonBest={};
function champOf(s){if(seasonBest[s.year]!==undefined)return seasonBest[s.year];const map={};for(const c of s.titles){for(const p of c.w){const a=map[p]||(map[p]={id:p,t:0,mj:0,f:0,w:0});a.t++;if(MAJORS.includes(c.t))a.mj++;a.f++;}for(const p of c.l){const a=map[p]||(map[p]={id:p,t:0,mj:0,f:0,w:0});a.f++;}}
  for(const r of PS){if(r.y!==s.year||!inLens(r.c))continue;const a=map[r.p]||(map[r.p]={id:r.p,t:0,mj:0,f:0,w:0});a.w+=r.w;a.l=(a.l||0)+r.l;}
  const ranked=Object.values(map).sort(playerOrder);const majors=s.titles.filter(c=>MAJORS.includes(c.t));return seasonBest[s.year]={best:ranked[0]||null,ranked,majors};}

/* ---------- theme ---------- */
function applyTheme(){let sel=$('#theme'),v=sel.value,root=document.documentElement,acc,sec,ter,ink;
  if(v==='champion'){const b=state.whole?playerAgg().sort(playerOrder)[0]:champOf(byYear[state.year]).best;const c=b?pnat(b.id):null;acc=c?natColor(c):'#c8e06a';sec='#f4f4f2';ter='#0b120b';ink=onColor(acc);sel.options[0].textContent=`Champion’s colours · ${b?pname(b.id):'—'}`;}
  else if(SURF[v]){acc=SURF[v];sec='#f4f4f2';ter='#0b120b';ink=onColor(acc);}
  else{acc=natColor(v);sec='#f4f4f2';ter='#0b120b';ink=onColor(acc);}
  root.style.setProperty('--accent',acc);root.style.setProperty('--accent2',sec);root.style.setProperty('--accent3',ter);root.style.setProperty('--on-accent',ink);}

/* ---------- the serve (the opening, once per visit) ---------- */
function lightsOut(){const box=$('#lights');let seen=false;try{seen=sessionStorage.getItem('apex-serve')==='1';}catch(e){}
  const out=()=>{if(!box.isConnected)return;box.classList.add('out');setTimeout(()=>box.remove(),800);try{sessionStorage.setItem('apex-serve','1');}catch(e){}};
  if(seen||RM){box.remove();return;}
  setTimeout(()=>box.classList.add('go'),400);setTimeout(()=>box.classList.add('over'),2400);setTimeout(out,3300);
  $('#skipLights').addEventListener('click',out);document.addEventListener('keydown',e=>{if(box.isConnected&&(e.key==='Enter'||e.key==='Escape'||e.key===' '))out();},{once:true});}

/* ---------- the River: share of titles by nation, year by year ---------- */
function smooth(pts){if(pts.length<3)return pts.map((p,i)=>(i?'L':'')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join('');let d='';for(let i=0;i<pts.length-1;i++){const p0=pts[i-1]||pts[i],p1=pts[i],p2=pts[i+1],p3=pts[i+2]||p2;const c1=[p1[0]+(p2[0]-p0[0])/6,p1[1]+(p2[1]-p0[1])/6],c2=[p2[0]-(p3[0]-p1[0])/6,p2[1]-(p3[1]-p1[1])/6];d+=`C${c1[0].toFixed(1)} ${c1[1].toFixed(1)} ${c2[0].toFixed(1)} ${c2[1].toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;}return d;}
let riverModel=null;
function buildRiver(){const years=S.map(s=>s.year),shares=[],totals=[],champs=[];const teamFirst={},teamTotal={};
  for(const s of S){const w={};let tot=0;for(const c of s.titles){const share=1/Math.max(1,c.w.length);for(const p of c.w){const n=pnat(p);w[n]=(w[n]||0)+share;}tot+=1;}
    for(const t in w){if(teamFirst[t]===undefined)teamFirst[t]=s.year;teamTotal[t]=(teamTotal[t]||0)+w[t];}
    const c=champOf(s);shares.push(w);totals.push(tot);champs.push({d:c.best?.id,t:c.best?pnat(c.best.id):null,rec:c.best?`${c.best.t} title${c.best.t===1?'':'s'}${c.best.mj?' · '+c.best.mj+' major'+(c.best.mj===1?'':'s'):''}`:'',majors:c.majors,races:s.titles.length,matches:s.matches});}
  const teams=Object.keys(teamFirst).sort((a,b)=>teamFirst[a]-teamFirst[b]||teamTotal[b]-teamTotal[a]);riverModel={years,shares,totals,champs,teams,teamTotal};}
function drawRiver(){
  if(!riverModel)buildRiver();const {years,shares,totals,champs,teams,teamTotal}=riverModel;
  const svg=$('#riverSvg'),box=svg.getBoundingClientRect(),W=Math.max(320,box.width),H=Math.max(200,box.height);svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
  if(!years.length){svg.innerHTML='';$('#riverAxis').innerHTML='';$('#riverLegend').innerHTML='';return;}
  const era=state.era==='all'?null:ERAS.find(e=>e.id===state.era);
  let i0=era?years.findIndex(y=>y>=era.from):0,i1=era?years.length-1-[...years].reverse().findIndex(y=>y<=era.to):years.length-1;if(i0<0||i1<i0){i0=0;i1=years.length-1;}const n=i1-i0+1;
  const padL=8,padR=era?64:56,top=40,bottom=26,plotH=H-top-bottom;
  const slotW=n===1?(W-padL-padR)*.42:(W-padL-padR)/(n-1);const x=i=>n===1?padL+(W-padL-padR)/2:padL+(i-i0)*slotW;
  const maxRaces=Math.max(1,...champs.slice(i0,i1+1).map(c=>c.races));const thick=i=>plotH*(era?0.45+0.55*champs[i].races/maxRaces:0.14+0.86*Math.sqrt(champs[i].races/maxRaces));const y0=i=>top+(plotH-thick(i))/2;
  const cum=years.map(()=>0);let bands='';const eraTotal={};for(let i=i0;i<=i1;i++)for(const t in shares[i])eraTotal[t]=(eraTotal[t]||0)+shares[i][t];
  const drawTeams=era?teams.filter(t=>eraTotal[t]>0):teams;
  for(const t of drawTeams){const up=[],down=[];let any=false;for(let i=i0;i<=i1;i++){const sh=totals[i]?(shares[i][t]||0)/totals[i]:0;const a=y0(i)+cum[i]*thick(i);const b=a+sh*thick(i);cum[i]+=sh;up.push([x(i),a]);down.push([x(i),b]);if(sh>0)any=true;}if(!any)continue;
    if(n===1){const w=slotW/2;up.unshift([up[0][0]-w,up[0][1]]);up.push([up[1][0]+w,up[1][1]]);down.unshift([down[0][0]-w,down[0][1]]);down.push([down[1][0]+w,down[1][1]]);}
    const dn=down.reverse();const d='M'+up[0][0].toFixed(1)+' '+up[0][1].toFixed(1)+smooth(up)+'L'+dn[0][0].toFixed(1)+' '+dn[0][1].toFixed(1)+smooth(dn)+'Z';const tot=era?eraTotal[t]:teamTotal[t];
    bands+=`<path class="band${state.focusTeam===t?' focus':''}" data-t="${esc(t)}" d="${d}" fill="${natColor(t)}" stroke="#07080a" stroke-width=".5"><title>${esc(natName(t))} · ${fmt(Math.round(tot))} titles ${era?'in this era':'since '+years[shares.findIndex(s=>s[t])]}</title></path>`;}
  let eras='';if(era){eras=`<text class="era-label" x="${padL}" y="${top-14}" style="fill:var(--accent)">${esc(era.name)} · ${era.from}–${era.to} · ${drawTeams.length} nations won a title</text>`;}
  else for(const e of ERAS){const k=years.findIndex(y=>y>=e.from);if(k<0)continue;const xx=x(k);const nxt=ERAS[ERAS.indexOf(e)+1];const nk=nxt?years.findIndex(y=>y>=nxt.from):-1;const slot=(nk>=0?x(nk):W)-xx;const fitW=l=>l.length*7.9+10<=slot;let label=ERA_SHORT[e.id]||e.name;if(!fitW(label))label=ERA_TINY[e.id]||'';const fits=!!label&&fitW(label);eras+=`<line class="era-line" x1="${xx.toFixed(1)}" y1="${top-6}" x2="${xx.toFixed(1)}" y2="${H-bottom+4}"/>${fits?`<text class="era-label" x="${(xx+5).toFixed(1)}" y="${top-14}">${esc(label)}</text>`:''}`;}
  let strip='',hits='';for(let i=i0;i<=i1;i++){const w=slotW;const c=champs[i];strip+=`<rect x="${(x(i)-w/2).toFixed(1)}" y="${H-bottom+8}" width="${Math.max(1,w-1).toFixed(1)}" height="8" fill="${c.t?natColor(c.t):'#333'}" rx="1"><title>${years[i]} · ${c.d?pname(c.d)+' · '+c.rec:'—'}</title></rect>`;hits+=`<rect class="yearhit" data-y="${years[i]}" x="${(x(i)-w/2).toFixed(1)}" y="0" width="${w.toFixed(1)}" height="${H}"/>`;}
  const si=years.indexOf(state.year);const selX=n>1&&!state.whole&&si>=i0&&si<=i1?x(si):-10;
  svg.innerHTML=`<g id="bands">${bands}</g>${eras}<g>${strip}</g><line class="cursor" id="riverCursor" x1="0" y1="${top-4}" x2="0" y2="${H-bottom+4}"/><line x1="${selX.toFixed(1)}" y1="${top-4}" x2="${selX.toFixed(1)}" y2="${H-bottom+16}" stroke="var(--accent)" stroke-width="2" pointer-events="none"/><g id="hits">${hits}</g>`;
  $('#riverStage').classList.toggle('hasfocus',!!state.focusTeam);
  const axisYears=era||n<=40?years.slice(i0,i1+1).filter((y,k,arr)=>arr.length<=14||k%Math.ceil(arr.length/12)===0||k===arr.length-1):[years[0]].concat(years.filter(y=>y%20===0&&y-years[0]>=8&&years[years.length-1]-y>=4),[years[years.length-1]]);
  $('#riverAxis').innerHTML=axisYears.map(y=>`<span>${y}</span>`).join('');
  const legend=$('#riverLegend');const scoreOf=era?eraTotal:teamTotal;const topN=[...drawTeams].sort((a,b)=>(scoreOf[b]||0)-(scoreOf[a]||0)).slice(0,14);if(state.focusTeam&&!(scoreOf[state.focusTeam]>0))state.focusTeam=null;
  legend.innerHTML=topN.map(t=>`<button type="button" data-t="${esc(t)}" class="${state.focusTeam===t?'on':''}"><i style="background:${natColor(t)}"></i>${esc(natName(t))}</button>`).join('');
  if(!legend.dataset.built){legend.dataset.built='1';legend.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;state.focusTeam=state.focusTeam===b.dataset.t?null:b.dataset.t;drawRiver();});}
  const tip=$('#riverTip'),stage=$('#riverStage');
  svg.onmousemove=e=>{const hit=e.target.closest('.yearhit');if(!hit){tip.classList.remove('show');$('#riverCursor').style.opacity=0;return;}const y=+hit.dataset.y,i=years.indexOf(y);const cx=x(i);const cur=$('#riverCursor');cur.setAttribute('x1',cx);cur.setAttribute('x2',cx);cur.style.opacity=1;
    const top5=Object.entries(shares[i]).sort((a,b)=>b[1]-a[1]).slice(0,5);const c=champs[i];
    tip.innerHTML=`<div class="yr">${y}</div><div class="small muted" style="margin:2px 0 8px">${c.races} titles${c.matches?' · '+fmt(c.matches)+' matches':''}${c.d?` · most titles <b style="color:var(--ink)">${esc(pname(c.d))}</b> ${c.rec}`:''}</div>${c.majors.slice(0,4).map(m=>`<div class="row"><span><i class="sw" style="background:${pcolor(m.w[0])}"></i>${esc(TOURN[m.t]?.n||m.t)}</span><span>${esc(pnames(m.w))}</span></div>`).join('')}${top5.map(([t,p])=>`<div class="row"><span><i class="sw" style="background:${natColor(t)}"></i>${esc(natName(t))}</span><span>${totals[i]?Math.round(p/totals[i]*100):0}%</span></div>`).join('')}<div class="small dim" style="margin-top:8px">Share of the year’s titles by nation · click to open</div>`;
    const r=stage.getBoundingClientRect();let px=e.clientX-r.left;px=Math.max(150,Math.min(r.width-150,px));tip.style.left=px+'px';tip.style.top='12px';tip.classList.add('show');};
  svg.onmouseleave=()=>{tip.classList.remove('show');$('#riverCursor').style.opacity=0;};
  svg.onclick=e=>{const b=e.target.closest('.band');const hit=e.target.closest('.yearhit');if(hit){setSeason(+hit.dataset.y,true);}else if(b){state.focusTeam=state.focusTeam===b.dataset.t?null:b.dataset.t;drawRiver();}};
}

/* ---------- the Courts (the Grid): tournaments listed, in the colour of their surface ---------- */
function courtModel(){const eds=eraEditions().filter(e=>!e.team&&e.level!=='D');const m={};
  const mk=(t,y)=>m[t]||(m[t]={cid:t,years:new Set(),first:y,last:y,surf:{},name:TOURN[t]?.n||t,place:(TOURN[t]?.city||'').split(' · ')[0],major:!!TOURN[t]?.major,level:{}});
  for(const e of eds){const c=mk(e.t,e.y);c.years.add(e.y);c.first=Math.min(c.first,e.y);c.last=Math.max(c.last,e.y);c.surf[e.surface]=(c.surf[e.surface]||0)+1;c.level[e.level]=(c.level[e.level]||0)+1;}
  const [y0,y1]=eraRange();const wins={};for(const c of CHAMPS){if(!inLens(c.c)||c.y<y0||c.y>y1)continue;if(!m[c.t]&&!(TOURN[c.t]?.major||EDS[c.id]))continue;const t=mk(c.t,c.y);t.years.add(c.y);t.first=Math.min(t.first,c.y);t.last=Math.max(t.last,c.y);if(!EDS[c.id]&&TOURN[c.t]?.s)t.surf[TOURN[c.t].s]=(t.surf[TOURN[c.t].s]||0)+1;const w=wins[c.t]||(wins[c.t]={});for(const p of c.w)w[p]=(w[p]||0)+1;}
  return Object.values(m).map(c=>{const s=Object.entries(c.surf).sort((a,b)=>b[1]-a[1])[0]?.[0]||TOURN[c.cid]?.s||'Unknown';const top=Object.entries(wins[c.cid]||{}).sort((a,b)=>b[1]-a[1])[0]||null;const lv=Object.entries(c.level).sort((a,b)=>b[1]-a[1])[0]?.[0]||(c.major?'G':'A');return {...c,count:c.years.size,surface:s,top:top?top[0]:null,topN:top?top[1]:0,lv,rank:LEVEL_RANK[lv]||0};});}
function drawGrid(){const list=courtModel();const q=state.gridFind.trim().toLowerCase();const team=eraEditions().filter(e=>e.team||e.level==='D').length;let shown=list.filter(c=>(q||c.count>=state.gridMin||c.major)&&(!q||(c.name+' '+c.place).toLowerCase().includes(q)));
  const sorters={count:(a,b)=>(b.major-a.major)||b.count-a.count||b.rank-a.rank||a.name.localeCompare(b.name),name:(a,b)=>a.name.localeCompare(b.name),surface:(a,b)=>a.surface.localeCompare(b.surface)||b.count-a.count,recent:(a,b)=>b.last-a.last||b.count-a.count,level:(a,b)=>b.rank-a.rank||b.count-a.count};shown.sort(sorters[state.gridSort]);
  const bigN=state.gridSort==='count'&&!q?Math.min(6,shown.filter(c=>c.major).length||4):0;
  $('#gridLede').textContent=`${list.length} tournaments in ${eraLabel().replace(' · ',', ')}${team?` (plus ${team.toLocaleString('en')} team ties, kept off the grid)`:''}. Each carries the colour of its surface and names the player who has won it most; the majors lead, then the events the tour has returned to most often.${shown.length<list.length&&!q?` Showing ${shown.length} with ${state.gridMin}+ editions.`:''}`;
  $('#circuits').innerHTML=shown.map((c,i)=>`<button type="button" class="circ flat${i<bigN?' big':''}" data-cid="${esc(c.cid)}" style="--team:${surfColor(c.surface)}" title="${esc(c.name)} · ${c.count} editions · ${c.first}–${c.last}${c.top?' · most titles: '+esc(pname(c.top))+' '+c.topN:''}"><span class="ct">${esc(c.place||'')}${c.place?' · ':''}${esc(c.surface)}${c.major?' · major':''}</span><span class="n">${c.count}</span><span class="nm">${esc(c.name)}</span><span class="yrs">${c.first}${c.last!==c.first?'–'+c.last:''}${c.top?' · <i style="background:'+pcolor(c.top)+'"></i>'+esc(pname(c.top))+' '+c.topN:''}</span></button>`).join('')||`<p class="muted">No tournament matches.</p>`;}

/* ---------- Stage: tabs, era strip, era context ---------- */
const TABS=[['season','Season'],['draw','Draw'],['players','Players'],['nations','Nations'],['tournaments','Tournaments'],['records','Records'],['barcode','Barcode'],['duel','Duel']];
function drawTabs(){$('#tabs').innerHTML=TABS.map(([id,l])=>`<button type="button" role="tab" data-tab="${id}" aria-pressed="${state.tab===id}">${l}</button>`).join('');
  $('#stageStatus').textContent=(state.tab==='season'||state.tab==='draw')&&!state.whole?`${state.year} · ${eraOf(state.year)?.name||''} · ${lensLabel()}`:eraLabel();}
function drawEraStrip(preview){const strip=$('#eraStrip');if(!strip.children.length)strip.innerHTML=ERAS.map(e=>`<button type="button" style="--w:${e.to-e.from+1}" data-era="${e.id}" title="${esc(e.name)} · ${e.from}–${e.to}" aria-label="${esc(e.name)} ${e.from}–${e.to}"></button>`).join('');
  for(const b of strip.children){b.classList.toggle('on',state.era===b.dataset.era);b.classList.toggle('demo',preview===b.dataset.era);}
  const e=preview?ERAS.find(x=>x.id===preview):state.era==='all'?eraOf(state.year):ERAS.find(x=>x.id===state.era);
  $('#eraCaption').innerHTML=`<span><b>${esc(e.name)}</b> · ${e.from}–${e.to}</span><span class="dim">${state.era===e.id?'Lens on · click again to release':'Click a segment to focus the whole page on that era'}</span>`;
  const ctx=$('#eraContext');ctx.innerHTML=`<div class="era-car">${e.ball.svg}</div><div><p class="eyebrow">${state.era===e.id?'Era lens':preview?'Era':'Era of the selected season'} · ${e.from}–${e.to}</p><h3>${esc(e.name)}</h3><p>${esc(e.text)}</p><div class="chips">${e.ball.features.map(f=>`<span>${esc(f)}</span>`).join('')}</div><p class="small dim" style="margin:10px 0 0">${esc(e.ball.label)} · an editorial reading of the period; the archive itself is not divided</p></div>`;}
const tour={i:-1,timer:null,visible:false,stopped:RM};
function tourStep(){if(tour.stopped||!tour.visible)return;tour.i=(tour.i+1)%ERAS.length;const ctx=$('#eraContext');ctx.classList.add('swap');setTimeout(()=>{if(tour.stopped)return;drawEraStrip(ERAS[tour.i].id);ctx.classList.remove('swap');},260);tour.timer=setTimeout(tourStep,4200);}
function tourStart(){if(tour.stopped||tour.timer)return;tour.timer=setTimeout(tourStep,1800);}
function tourPause(){clearTimeout(tour.timer);tour.timer=null;}
function tourStop(){if(tour.stopped)return;tour.stopped=true;tourPause();$('#eraContext').classList.remove('swap');drawEraStrip();}

/* ---------- shared pieces ---------- */
const champOfEd=id=>CHAMPS.find(c=>c.id===id||c.m===id);
const edName=e=>TOURN[e.t]?.n||e.name;
const pl=id=>`<a href="#" data-player="${esc(id)}" style="color:inherit">${esc(pname(id))}</a>`;
const pls=ids=>(ids||[]).map(pl).join(' / ');
const flag=id=>`<i class="dot" style="--c:${pcolor(id)}"></i>`;
function edCard(e,on){const c=champOfEd(e.id);const w=c?c.w[0]:null;return `<button type="button" class="cal${on?' on':''}" data-edition="${esc(e.id)}" style="--team:${surfColor(e.surface)}"><div class="rd">${esc(dm(e.date))} · ${esc(levelName(e.level))}${e.draw?' · '+e.draw:''}</div><div class="sc"><span>${esc(e.surface)}</span></div><div class="nm">${esc(edName(e))}</div><div class="w">${c?'<i class="dot" style="--c:'+pcolor(w)+'"></i>'+esc(pnames(c.w))+(c.l.length?' d. '+esc(pnames(c.l)):''):e.n?e.n+' matches':'no result recorded'}</div></button>`;}
function natBars(rows,valOf,subOf,max,unit=''){return `<div class="board">${rows.map((a,i)=>`<button type="button" class="bar" data-nation="${esc(a.id)}" style="--i:${i};${teamVar(a.id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(natName(a.id))}<small> ${a.t} titles · ${a.mj} majors</small></span><small>${subOf(a)}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*valOf(a)/(max||1))}%"></span></span></span><span class="val">${valOf(a)}${unit}</span></button>`).join('')}</div>`;}
function playerBars(rows,valOf,subOf,max,unit=''){return `<div class="board">${rows.map((a,i)=>`<button type="button" class="bar" data-player="${esc(a.id)}" style="--i:${i};--team:${pcolor(a.id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(pname(a.id))}<small> ${esc(natName(pnat(a.id)))}</small></span><small>${subOf(a)}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*valOf(a)/(max||1))}%"></span></span></span><span class="val">${valOf(a)}${unit}</span></button>`).join('')}</div>`;}
function drawChart(el,series,n,labelOf,xl,colorOf){const box=el.getBoundingClientRect(),W=Math.max(300,box.width),H=Math.max(200,box.height);const padL=34,padR=130,padT=14,padB=26;const max=Math.max(1,...series.flatMap(s=>s.pts));const x=i=>padL+(n?i*(W-padL-padR)/n:0),y=v=>padT+(H-padT-padB)*(1-v/max);
  let g='';const step=max>200?100:max>60?25:max>20?10:max>8?5:1;for(let v=0;v<=max;v+=step)g+=`<line class="gridl" x1="${padL}" x2="${W-padR}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/><text class="lb" x="${padL-6}" y="${(y(v)+3).toFixed(1)}" text-anchor="end">${v}</text>`;
  for(let i=0;i<n;i++){const l=xl(i);if(l)g+=`<text class="lb" x="${x(i+1).toFixed(1)}" y="${H-8}" text-anchor="middle">${esc(l)}</text>`;}
  const paths=series.map(s=>{const d=s.pts.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)).join('');const last=s.pts[s.pts.length-1];return `<path class="ser" d="${d}" style="--c:${colorOf(s.id)}"><title>${esc(labelOf(s.id))} · ${fmt(last)}</title></path><text class="end" x="${(x(n)+6).toFixed(1)}" y="${(y(last)+4).toFixed(1)}" style="--c:${colorOf(s.id)}">${esc(labelOf(s.id))} ${fmt(last)}</text>`;}).join('');
  el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Cumulative chart">${g}${paths}</svg>`;}
const age=(dob,date)=>{if(!dob||!date||dob.length<8)return null;const y=+dob.slice(0,4),m=+dob.slice(4,6),d=+dob.slice(6,8);const Y=+date.slice(0,4),M=+date.slice(5,7),D=+date.slice(8,10);let a=Y-y;if(M<m||(M===m&&D<d))a--;return a;};

/* ---------- Season ---------- */
function seasonView(){if(state.whole)return eraView();const s=byYear[state.year];if(!s){$('#view').innerHTML='<p class="muted">No season in this lens.</p>';return;}
  const {best,ranked,majors}=champOf(s);const partial=String(s.year)===(A.lastDate||'').slice(0,4);const eds=s.editions.filter(e=>!e.team&&e.level!=='D');const team=s.editions.length-eds.length;
  const podium=ranked.slice(0,3);const order=[podium[1],podium[0],podium[2]];
  const head=`<div class="season-head"><div class="champ-card" style="${best?`--accent:${pcolor(best.id)};--on-accent:${onColor(pcolor(best.id))}`:''}"><p class="eyebrow" style="color:var(--ink);opacity:.7">${partial?'Season in progress · results through '+esc(day(A.lastDate)):'Most titles of the year'} · ${esc(lensLabel())}</p><div class="yr">${s.year}</div>${best?`<div class="who"><small>${partial?'Leads the year':'Most titles'} · ${best.t} title${best.t===1?'':'s'}${best.mj?' · '+best.mj+' major'+(best.mj===1?'':'s'):''}</small><a href="#" data-player="${esc(best.id)}" style="color:inherit;text-decoration:none">${esc(pname(best.id))}</a></div><div class="team"><i></i>${esc(natName(pnat(best.id)))}</div><div class="facts"><div><b>${best.w}–${best.l||0}</b>matches</div><div><b>${best.f}</b>finals</div><div><b>${s.titles.length}</b>titles this year</div><div><b>${eds.length}</b>tournaments</div></div>`:`<div class="who"><small>No titles recorded</small>—</div>`}
  ${majors.map(m=>`<p class="small" style="margin:14px 0 0;color:var(--ink);opacity:.85">${esc(TOURN[m.t]?.n||m.t)}: <b>${esc(pnames(m.w))}</b>${m.l.length?' d. '+esc(pnames(m.l)):''}${m.s?' · '+esc(m.s):''}</p>`).join('')}<p class="small dim" style="margin:${majors.length?6:18}px 0 0">Ranked by titles, then majors, then finals, then match wins; a reading of the roll of honour, not an official award.</p></div>
  <div><div class="podium">${order.map((d,i)=>d?`<button type="button" class="step p${podium.indexOf(d)+1} bar" data-player="${esc(d.id)}" style="--h:${Math.round(120+120*Math.min(1,d.t/Math.max(1,podium[0].t)))}px;--team:${pcolor(d.id)};display:flex"><span class="pos">${podium.indexOf(d)+1}</span><span class="nm">${esc(pname(d.id))}</span><span class="pt">${d.t} title${d.t===1?'':'s'} · ${d.mj} major${d.mj===1?'':'s'} · ${d.w}–${d.l||0}</span></button>`:'<div></div>').join('')}<div class="base"></div></div></div></div>`;
  const cal=eds.length?`<div class="h3"><span>The year’s tournaments</span><small>${eds.length} events${team?' · '+team+' team ties not shown':''} · click one to open its draw</small></div><div class="calendar">${eds.map(e=>edCard(e,state.edition===e.id&&state.tab==='draw')).join('')}</div>`:`<div class="h3"><span>The year’s titles</span><small>from Wimbledon’s own records · full draws from 1968</small></div><div class="calendar">${s.titles.map(c=>`<button type="button" class="cal" data-tourn="${esc(c.t)}" style="--team:${surfColor(TOURN[c.t]?.s||'Unknown')}"><div class="rd">${c.y} · ${esc(c.c)}</div><div class="sc"><span>${esc(TOURN[c.t]?.s||'')}</span></div><div class="nm">${esc(TOURN[c.t]?.n||c.t)}</div><div class="w"><i class="dot" style="--c:${pcolor(c.w[0])}"></i>${esc(pnames(c.w))}${c.l.length?' d. '+esc(pnames(c.l)):''}</div></button>`).join('')}</div>`;
  // table of the year by nation, and the race for titles among the top players
  const nat={};for(const c of s.titles){for(const p of c.w){const n=pnat(p);const a=nat[n]||(nat[n]={id:n,t:0,mj:0,f:0,w:0,l:0});a.t+=1/c.w.length;if(MAJORS.includes(c.t))a.mj+=1/c.w.length;}}
  for(const r of PS){if(r.y!==s.year||!inLens(r.c))continue;const n=pnat(r.p);const a=nat[n]||(nat[n]={id:n,t:0,mj:0,f:0,w:0,l:0});a.w+=r.w;a.l+=r.l;}
  const table=Object.values(nat).map(a=>({...a,t:Math.round(a.t),mj:Math.round(a.mj)})).sort((a,b)=>b.t-a.t||b.mj-a.mj||b.w-a.w).slice(0,20);
  const top6=ranked.slice(0,6).map(p=>p.id);const dated=s.titles.filter(c=>EDS[c.id]).map(c=>({d:EDS[c.id].date,w:c.w}));dated.sort((a,b)=>a.d<b.d?-1:1);
  const race=top6.length&&dated.length?`<div class="h3" style="margin-top:26px"><span>The race for titles</span><small>cumulative titles of the year’s top six, by tournament date</small></div><div class="chart" id="seasonChart"></div>`:'';
  const body=`<div class="two" style="margin-top:26px"><div class="panel"><div class="h3"><span>Table of the year</span><small>nations by titles, then majors</small></div>${natBars(table,a=>a.t,a=>`${a.w}–${a.l} in matches`,Math.max(1,...table.map(a=>a.t)))}</div><div class="panel"><div class="h3"><span>Finals of the year</span><small>${s.titles.length} titles · the biggest first</small></div><div class="board">${[...s.titles].sort((a,b)=>(LEVEL_RANK[EDS[b.id]?.level||'G']||0)-(LEVEL_RANK[EDS[a.id]?.level||'G']||0)||((EDS[a.id]?.date||'')<(EDS[b.id]?.date||'')?-1:1)).slice(0,14).map((c,i)=>`<button type="button" class="bar" data-edition="${esc(c.id)}" style="--i:${i};--team:${pcolor(c.w[0])}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(pnames(c.w))}<small> d. ${esc(pnames(c.l))||'—'}</small></span><small>${esc(TOURN[c.t]?.n||c.t)} · ${esc(EDS[c.id]?.surface||TOURN[c.t]?.s||'')}${c.s?' · '+esc(c.s):''}</small></span></span><span class="val" style="font-size:12px">${esc(levelName(EDS[c.id]?.level||'G'))}</span></button>`).join('')}</div></div></div>`;
  $('#view').innerHTML=head+cal+race+body;
  if(race){const n=dated.length;const series=top6.map(id=>{let c=0;const pts=[0];for(const d of dated){if(d.w.includes(id))c++;pts.push(c);}return {id,pts};});const months=dated.map(d=>d.d.slice(5,7));drawChart($('#seasonChart'),series,n,pname,i=>{const m=months[i];return i===0||months[i-1]!==m?new Date(2000,+m-1,1).toLocaleDateString('en-GB',{month:'short'}):'';},pcolor);}}
function eraView(){const ss=eraSeasons();const e=state.era==='all'?null:ERAS.find(x=>x.id===state.era);const titles=eraTitles();const eds=eraEditions().filter(x=>!x.team&&x.level!=='D');
  const players=playerAgg().sort(playerOrder);const top=players[0];const nations=natAgg().sort((a,b)=>b.t-a.t||b.mj-a.mj).slice(0,12);
  const head=`<div class="season-head"><div class="champ-card" style="${top?`--accent:${pcolor(top.id)};--on-accent:${onColor(pcolor(top.id))}`:''}"><p class="eyebrow" style="color:var(--ink);opacity:.7">${e?'Whole era':'All seasons'} · ${esc(lensLabel())}</p><div class="yr" style="font-size:clamp(44px,6vw,84px)">${ss[0]?.year}–${ss[ss.length-1]?.year}</div>${top?`<div class="who"><small>Most titles across the period · ${top.t} titles · ${top.mj} majors</small><a href="#" data-player="${esc(top.id)}" style="color:inherit;text-decoration:none">${esc(pname(top.id))}</a></div><div class="team"><i></i>${esc(natName(pnat(top.id)))}</div>`:''}<div class="facts"><div><b>${fmt(titles.length)}</b>titles</div><div><b>${fmt(eds.length)}</b>tournaments</div><div><b>${ss.length}</b>seasons</div><div><b>${fmt(players.length)}</b>players</div></div></div>
  <div><div class="podium">${[players[1],players[0],players[2]].map((d,i)=>d?`<button type="button" class="step p${players.indexOf(d)+1} bar" data-player="${esc(d.id)}" style="--h:${Math.round(120+120*d.t/Math.max(1,players[0].t))}px;--team:${pcolor(d.id)};display:flex"><span class="pos">${players.indexOf(d)+1}</span><span class="nm">${esc(pname(d.id))}</span><span class="pt">${d.t} titles · ${d.mj} majors</span></button>`:'<div></div>').join('')}<div class="base"></div></div></div></div>`;
  const roll=ss.map(s=>({s,c:champOf(s)}));
  const rollHtml=`<div class="h3"><span>Most titles, year by year</span><small>click a year to open it</small></div><div class="calendar">${roll.map(({s,c})=>`<button type="button" class="cal" data-year="${s.year}" style="--team:${c.best?pcolor(c.best.id):'#5b616b'}"><div class="rd">${s.year}</div><div class="nm">${c.best?esc(pname(c.best.id)):'—'}</div><div class="w">${c.best?c.best.t+' title'+(c.best.t===1?'':'s')+(c.best.mj?' · '+c.best.mj+' major'+(c.best.mj===1?'':'s'):''):''}</div></button>`).join('')}</div>`;
  const body=`<div class="two" style="margin-top:26px"><div class="panel"><div class="h3"><span>Nations across the period</span><small>by titles</small></div>${natBars(nations,a=>a.t,a=>`${a.np} players · ${a.nw} title winners`,Math.max(1,...nations.map(a=>a.t)))}</div><div class="panel"><div class="h3"><span>Players across the period</span><small>by titles, then majors</small></div>${playerBars(players.slice(0,12),a=>a.t,a=>`${a.mj} majors · ${a.f} finals · ${a.w}–${a.l}`,Math.max(1,...players.slice(0,12).map(a=>a.t)))}</div></div>`;
  $('#view').innerHTML=head+rollHtml+body;}

/* ---------- the matches of a season: embedded offline, fetched per year on the site ---------- */
let replay=null;
function stopReplay(){if(replay){clearTimeout(replay.timer);replay=null;}}
let loading={};
function loadDetails(year){if(DETAILS[year])return Promise.resolve(DETAILS[year]);if(!DETAIL_URL)return Promise.resolve(null);if(loading[year])return loading[year];
  return loading[year]=fetch(DETAIL_URL+year+'.json').then(r=>r.ok?r.json():null).then(d=>{if(d)DETAILS[year]=d;delete loading[year];return d;}).catch(()=>{delete loading[year];return null;});}
const matchRows=(year,eid)=>(DETAILS[year]?.[eid]||[]).map(r=>unpack(MF,r));
const ROUNDS=['R128','R64','R32','R16','QF','SF','F','RR','BR','ER'];
const roundName={R128:'First round · 128',R64:'Round of 64',R32:'Round of 32',R16:'Round of 16',QF:'Quarter-finals',SF:'Semi-finals',F:'Final',RR:'Round robin',BR:'Bronze match',ER:'Early round'};
const seedOf=s=>s?String(s).replace(/^(\d+)$/,'[$1]'):'';
function defaultEdition(s){const eds=s.editions.filter(e=>!e.team&&e.level!=='D');if(!eds.length)return null;const mj=eds.filter(e=>MAJORS.includes(e.t));if(mj.length)return mj[mj.length-1].id;return [...eds].sort((a,b)=>(LEVEL_RANK[b.level]||0)-(LEVEL_RANK[a.level]||0)||(a.date<b.date?1:-1))[0].id;}
function matchLine(m,champ){const w=m.w,l=m.l;const on=state.match===m.id;const path=champ&&w.some(p=>champ.includes(p));return `<button type="button" class="bm${on?' on':''}${path?' path':''}" data-match="${esc(m.id)}"><span class="p w"><i class="dot" style="--c:${pcolor(w[0])}"></i><span>${esc(pnames(w))}</span><small>${esc(seedOf(m.ws))}</small></span><span class="p l"><i class="dot" style="--c:${pcolor(l[0])}"></i><span>${esc(pnames(l))}</span><small>${esc(seedOf(m.ls))}</small></span><span class="s">${esc(m.s||'—')}</span></button>`;}
function drawView(){if(state.whole)return eraDrawsView();const s=byYear[state.year];if(!s){$('#view').innerHTML='<p class="muted">No season in this lens.</p>';return;}
  const eds=s.editions.filter(e=>!e.team&&e.level!=='D');let e=EDS[state.edition];if(!e||e.y!==s.year||!inLens(e.c)||e.team){state.edition=defaultEdition(s);e=EDS[state.edition];}
  if(!e){const titles=s.titles;$('#view').innerHTML=`<div class="panel"><div class="h3"><span>${s.year} · the roll of honour</span><small>full draws exist from 1968; before that Wimbledon’s own records give the champions</small></div><div class="board">${titles.map((c,i)=>`<button type="button" class="bar" data-tourn="${esc(c.t)}" style="--i:${i};--team:${pcolor(c.w[0])}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(pnames(c.w))}<small> d. ${esc(pnames(c.l))||'—'}</small></span><small>${esc(TOURN[c.t]?.n||c.t)} · ${esc(c.c)}${c.s?' · '+esc(c.s):''}</small></span></span></button>`).join('')||'<p class="muted">No titles in this lens.</p>'}</div></div>`;return;}
  const many=eds.length>36;const nav=`<div class="chiplist${many?' many':''}" id="matchNav" style="margin-top:20px">${eds.map(x=>`<button type="button" class="chip${x.id===e.id?' on':''}" data-edition="${esc(x.id)}" style="${x.id===e.id?'border-color:var(--accent);color:var(--accent)':''}"><i style="--c:${surfColor(x.surface)}"></i>${esc(dm(x.date))} ${esc(edName(x)).slice(0,26)}${MAJORS.includes(x.t)?' ★':''}</button>`).join('')}</div>`;
  const c=champOfEd(e.id);const t=TOURN[e.t]||{};const rows=matchRows(s.year,e.id);const champ=c?c.w:null;
  const head=`<div class="card" style="margin-top:18px;grid-template-columns:1fr;--team:${surfColor(e.surface)}"><div class="panel" style="display:flex;flex-wrap:wrap;gap:18px;align-items:flex-end;justify-content:space-between"><div><p class="eyebrow">${esc(levelName(e.level))} · ${esc(e.surface)} · ${esc(day(e.date))}${e.draw?' · draw of '+e.draw:''} · ${esc(e.c==='MS'?'ATP singles':e.c==='WS'?'WTA singles':e.c==='MD'?'ATP doubles':'WTA doubles')}</p><h2 style="margin:6px 0 0"><a href="#" data-tourn="${esc(e.t)}" style="color:inherit;text-decoration:none">${esc(edName(e))}</a> <span class="muted" style="font-size:.6em;font-weight:600;font-style:normal">${esc((t.city||'').split(' · ')[0])}</span></h2></div>${c?`<div class="champline" style="--team:${pcolor(c.w[0])}"><span class="eyebrow">Champion</span><b>${pls(c.w)}</b><span class="small muted">d. ${pls(c.l)||'—'}${c.s?' · '+esc(c.s):''}</span></div>`:'<div class="champline"><span class="eyebrow">Champion</span><b class="muted">not recorded</b></div>'}</div></div>`;
  let bracket='';
  if(!rows.length){bracket=`<p class="muted" style="margin-top:18px">${DETAIL_URL&&!DETAILS[s.year]?'Loading the matches of '+s.year+'…':'No match records for this edition; the roll of honour above is what the archive holds.'}</p>`;}
  else{const byR={};for(const m of rows)(byR[m.r]||(byR[m.r]=[])).push(m);for(const r in byR)byR[r].sort((a,b)=>(a.n||0)-(b.n||0));
    const present=ROUNDS.filter(r=>byR[r]);const cols=present.filter(r=>!['RR','BR','ER'].includes(r)&&byR[r].length<=16);const early=present.filter(r=>!cols.includes(r)&&!['RR','BR','ER'].includes(r));
    const rr=byR.RR?`<details class="round" open><summary>${roundName.RR} · ${byR.RR.length} matches</summary><div class="bmlist">${byR.RR.map(m=>matchLine(m,champ)).join('')}</div></details>`:'';
    const earlyHtml=early.map(r=>`<details class="round"><summary>${roundName[r]||r} · ${byR[r].length} matches${champ&&byR[r].some(m=>m.w.some(p=>champ.includes(p)))?' · <span style="color:var(--accent)">the champion’s match is marked</span>':''}</summary><div class="bmlist">${byR[r].map(m=>matchLine(m,champ)).join('')}</div></details>`).join('');
    const colsHtml=cols.length?`<div class="bracket" id="bracket" style="--cols:${cols.length}">${cols.map((r,k)=>`<div class="bcol" style="--i:${k}"><div class="bhead">${esc(roundName[r]||r)}<small>${byR[r].length}</small></div>${byR[r].map(m=>matchLine(m,champ)).join('')}</div>`).join('')}${byR.BR?`<div class="bcol" style="--i:${cols.length}"><div class="bhead">${roundName.BR}</div>${byR.BR.map(m=>matchLine(m,champ)).join('')}</div>`:''}</div>`:'';
    bracket=`<div class="h3" style="margin-top:22px"><span>The draw</span><small>${rows.length} matches · the champion’s path is lit · <button type="button" class="linkbtn" id="replayDraw">replay the build</button></small></div>${rr}${earlyHtml}${colsHtml}`;}
  let sheet='';const m=rows.find(x=>x.id===state.match)||(rows.length?byR_final(rows):null);if(m){state.match=m.id;sheet=matchSheet(m,e);}
  $('#view').innerHTML=nav+head+bracket+sheet;
  {const on=$('#matchNav .chip.on');if(on&&many){const nv=$('#matchNav');nv.scrollTop=Math.max(0,on.offsetTop-nv.clientHeight/2+on.offsetHeight/2);}}
  const rb=$('#replayDraw');if(rb)rb.onclick=()=>{const b=$('#bracket');if(!b)return;b.classList.remove('build');void b.offsetWidth;b.classList.add('build');};
  if($('#bracket')&&!RM)$('#bracket').classList.add('build');
  if(!rows.length&&DETAIL_URL&&!DETAILS[s.year]){loadDetails(s.year).then(()=>{if(state.tab==='draw'&&state.year===s.year)render();});}}
function byR_final(rows){return rows.find(x=>x.r==='F')||rows[rows.length-1];}
const statRow=(l,a,b,fa,fb)=>`<tr><td class="n">${a==null?'—':esc(fa??a)}</td><td class="lab">${l}</td><td class="n">${b==null?'—':esc(fb??b)}</td></tr>`;
function matchSheet(m,e){const w=m.w,l=m.l;const st=m.st;const S=A.statFields||[];const get=(row,k)=>{if(!st||!st[row])return null;const i=S.indexOf(k);return i<0?null:st[row][i];};
  const pc=(a,b)=>a!=null&&b?Math.round(100*a/b)+'%':null;
  const rows=st?[statRow('Aces',get(0,'ace'),get(1,'ace')),statRow('Double faults',get(0,'df'),get(1,'df')),statRow('Service points',get(0,'svpt'),get(1,'svpt')),statRow('First serves in',pc(get(0,'1stIn'),get(0,'svpt')),pc(get(1,'1stIn'),get(1,'svpt'))),statRow('First-serve points won',pc(get(0,'1stWon'),get(0,'1stIn')),pc(get(1,'1stWon'),get(1,'1stIn'))),statRow('Second-serve points won',pc(get(0,'2ndWon'),get(0,'svpt')!=null&&get(0,'1stIn')!=null?get(0,'svpt')-get(0,'1stIn'):null),pc(get(1,'2ndWon'),get(1,'svpt')!=null&&get(1,'1stIn')!=null?get(1,'svpt')-get(1,'1stIn'):null)),statRow('Service games',get(0,'SvGms'),get(1,'SvGms')),statRow('Break points saved',get(0,'bpSaved')!=null?`${get(0,'bpSaved')}/${get(0,'bpFaced')}`:null,get(1,'bpSaved')!=null?`${get(1,'bpSaved')}/${get(1,'bpFaced')}`:null),statRow('Break points converted',get(1,'bpFaced')!=null?`${get(1,'bpFaced')-get(1,'bpSaved')}/${get(1,'bpFaced')}`:null,get(0,'bpFaced')!=null?`${get(0,'bpFaced')-get(0,'bpSaved')}/${get(0,'bpFaced')}`:null)].join(''):'';
  const sets=(m.s||'').split(' ').filter(x=>/\d/.test(x));const setsHtml=sets.map(x=>{const mm=/^(\d+)-(\d+)(?:\((\d+)\))?/.exec(x);if(!mm)return `<span class="set"><b>${esc(x)}</b></span>`;const a=+mm[1],b=+mm[2];return `<span class="set${a>b?' won':' lost'}"><b>${a}</b><b>${b}</b>${mm[3]?`<small>${mm[3]}</small>`:''}</span>`;}).join('');
  return `<div class="card sheet" style="margin-top:22px;grid-template-columns:1fr;--team:${pcolor(w[0])}"><div class="panel"><p class="eyebrow">${esc(roundName[m.r]||m.r)} · ${esc(edName(e))} ${e.y} · ${esc(e.surface)}${m.bo?' · best of '+m.bo:''}${m.mins?' · '+m.mins+' minutes':''}${/RET|W\/O|DEF/i.test(m.s||'')?' · '+(/W\/O/i.test(m.s)?'walkover':/DEF/i.test(m.s)?'default':'retirement'):''}</p>
  <div class="sheet-heads"><div class="who w" style="--team:${pcolor(w[0])}"><small>${esc(natName(pnat(w[0])))}${m.wr?' · rank '+m.wr:''}${m.ws?' · seed '+esc(m.ws):''}</small><b>${pls(w)}</b></div><div class="score">${setsHtml||'<b>'+esc(m.s||'—')+'</b>'}</div><div class="who l" style="--team:${pcolor(l[0])}"><small>${esc(natName(pnat(l[0])))}${m.lr?' · rank '+m.lr:''}${m.ls?' · seed '+esc(m.ls):''}</small><b>${pls(l)}</b></div></div>
  ${rows?`<div class="tablewrap" style="max-height:none;margin-top:14px"><table class="stats"><tr><th class="n">${esc(pname(w[0]))}</th><th></th><th class="n">${esc(pname(l[0]))}</th></tr>${rows}</table></div>`:'<p class="small dim" style="margin:12px 0 0">No serve statistics recorded for this match; the tour’s match statistics begin in 1991 and are patchy before the 2000s.</p>'}
  ${w.length===1&&l.length===1?`<p class="small muted" style="margin:12px 0 0"><a href="#" data-duel="${esc(w[0])}|${esc(l[0])}">Open the head-to-head →</a></p>`:''}</div></div>`;}
function eraDrawsView(){const ss=eraSeasons();const titles=eraTitles().filter(c=>MAJORS.includes(c.t)||LEVEL_RANK[EDS[c.id]?.level||'G']>=5);const byT={};for(const c of titles)(byT[c.t]||(byT[c.t]=[])).push(c);
  const order=Object.keys(byT).sort((a,b)=>(TOURN[b]?.major?1:0)-(TOURN[a]?.major?1:0)||byT[b].length-byT[a].length);
  $('#view').innerHTML=`<div class="h3" style="margin-top:20px"><span>The biggest titles across the period</span><small>majors, Tour Finals and the Olympic tournament · click a year to open its draw</small></div>${order.map(t=>`<div class="panel" style="margin-top:14px"><div class="h3"><span>${esc(TOURN[t]?.n||t)}</span><small>${byT[t].length} editions · ${esc(TOURN[t]?.s||'')}</small></div><div class="chiplist">${byT[t].map(c=>`<button type="button" class="chip" data-edition="${esc(c.id)}" data-year="${c.y}"><i style="--c:${pcolor(c.w[0])}"></i>${c.y} ${esc(pnames(c.w))}</button>`).join('')}</div></div>`).join('')||'<p class="muted">No titles in this lens.</p>'}`;}

/* ---------- Players ---------- */
function playersView(){const list=playerAgg();const lens=state.plens;let rows=list.filter(p=>p[lens]!=null);if(lens==='rate')rows=rows.filter(p=>p.p>=100);rows.sort((a,b)=>b[lens]-a[lens]||b.t-a.t||b.w-a.w);rows=rows.slice(0,40);
  const max=Math.max(1,...rows.map(a=>a[lens]));const q=(state.find2||'').toLowerCase();const found=q?Object.entries(PLAYERS).filter(([id,p])=>p.n.toLowerCase().includes(q)).slice(0,14):[];
  $('#view').innerHTML=`<div class="sect-head" style="margin-top:22px"><div><h2 style="font-size:24px;margin:0">Players · ${esc(eraLabel())}</h2></div><div class="small mono muted">${fmt(list.length)} players</div></div><div class="panel"><div class="tools" style="margin-bottom:14px"><input type="search" id="find2" placeholder="Search a player" value="${esc(state.find2||'')}" aria-label="Search"><select id="lens" aria-label="Lens">${Object.entries(PLENSES).map(([k,v])=>`<option value="${k}" ${k===lens?'selected':''}>${v[0]}</option>`).join('')}</select><span class="small muted">${esc(PLENSES[lens][1])}</span></div>${q?`<div class="chiplist" style="margin-bottom:14px">${found.map(([id,p])=>`<button type="button" class="chip" data-player="${esc(id)}"><i style="--c:${pcolor(id)}"></i>${esc(p.n)} <span class="dim">${esc(p.ioc||'')}</span></button>`).join('')||'<span class="muted small">No match.</span>'}</div>`:''}
  ${playerBars(rows,a=>a[lens],a=>`${a.first}–${a.last} · ${a.t} titles · ${a.mj} majors · ${a.w}–${a.l}`,max,/rate/.test(lens)?'%':'')}</div>`;
  $('#find2').addEventListener('input',e=>{state.find2=e.target.value;playersView();$('#find2').focus();const v=$('#find2');v.setSelectionRange(v.value.length,v.value.length);});$('#lens').addEventListener('change',e=>{state.plens=e.target.value;render();});}
function playerView(id){const p=PLAYERS[id];if(!p){playersView();return;}const all=playerAgg();const a=all.find(x=>x.id===id)||{id,w:0,l:0,t:0,f:0,mj:0,hw:0,hl:0,cw:0,cl:0,gw:0,gl:0,iw:0,il:0,first:null,last:null,p:0,rate:0};
  const rank=[...all].sort(playerOrder).findIndex(x=>x.id===id)+1;const [y0,y1]=eraRange();
  const titles=CHAMPS.filter(c=>c.w.includes(id)&&inLens(c.c)&&c.y>=y0&&c.y<=y1).sort((a,b)=>b.y-a.y||((EDS[a.id]?.date||'')<(EDS[b.id]?.date||'')?1:-1));const finalsLost=CHAMPS.filter(c=>c.l.includes(id)&&inLens(c.c)&&c.y>=y0&&c.y<=y1);
  const rows=psRows().filter(r=>r.p===id).sort((a,b)=>b.y-a.y||a.c.localeCompare(b.c));
  const majorsBy={};for(const c of titles)if(MAJORS.includes(c.t))majorsBy[c.t]=(majorsBy[c.t]||0)+1;
  const rivals=(RIVALS[id]||[]).slice(0,6);
  const surf=[['Hard',a.hw,a.hl],['Clay',a.cw,a.cl],['Grass',a.gw,a.gl],['Carpet & other',a.iw,a.il]].filter(x=>x[1]+x[2]>0);
  const born=p.dob&&p.dob.length>=8?`${p.dob.slice(6,8)}/${p.dob.slice(4,6)}/${p.dob.slice(0,4)}`:p.dob&&p.dob.length>=4?p.dob.slice(0,4):null;
  const kpi=(t,v,s)=>`<div class="kpi"><span>${t}</span><b>${v}</b>${s?`<small>${s}</small>`:''}</div>`;
  $('#view').innerHTML=`<div class="card" style="margin-top:20px;grid-template-columns:1fr;--team:${pcolor(id)}"><div class="panel" style="display:flex;flex-wrap:wrap;gap:20px;align-items:flex-end;justify-content:space-between"><div><p class="eyebrow">Player · ${esc(natName(p.ioc))}${p.hand?' · '+(p.hand==='L'?'left-handed':p.hand==='R'?'right-handed':'')+'':''}${p.height?' · '+p.height+' cm':''}${born?' · born '+esc(born):''}${a.first?' · '+a.first+'–'+a.last:''}</p><h2 style="margin:6px 0 0"><i class="dot" style="--c:${pcolor(id)};width:.5em;height:.5em;vertical-align:.1em;margin-right:8px"></i>${esc(p.n)}</h2></div>${rank?`<div class="small mono muted">#${rank} by titles in ${esc(eraLabel())}</div>`:''}</div></div>
  <div class="kpis" style="margin-top:16px">${kpi('Titles',a.t,titles.length!==a.t?'':'in the lens')}${kpi('Majors',a.mj,Object.keys(majorsBy).length?Object.entries(majorsBy).map(([t,n])=>`${TOURN[t]?.n} ${n}`).join(' · '):'')}${kpi('Finals',a.f,`${finalsLost.length} lost`)}${kpi('Matches',`${a.w}–${a.l}`,a.p?a.rate+'% won':'no match records before 1968')}${kpi('Best year',a.bestY||'—',a.best?a.best+' titles':'')}</div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Titles</span><small>${titles.length} in the lens · click one to open its draw</small></div><div class="board">${titles.slice(0,60).map((c,i)=>`<button type="button" class="bar" data-edition="${esc(c.id)}" data-year="${c.y}" style="--i:${i};--team:${surfColor(EDS[c.id]?.surface||TOURN[c.t]?.s||'Unknown')}"><span class="rk">${titles.length-i}</span><span><span class="lab"><span>${esc(TOURN[c.t]?.n||c.t)}<small> ${c.y}${MAJORS.includes(c.t)?' · major':''}</small></span><small>d. ${esc(pnames(c.l))||'—'}${c.s?' · '+esc(c.s):''}${c.w.length>1?' · with '+esc(pnames(c.w.filter(x=>x!==id))):''}</small></span></span><span class="val" style="font-size:12px">${esc(EDS[c.id]?.surface||TOURN[c.t]?.s||'')}</span></button>`).join('')||'<p class="muted small">No titles in this lens.</p>'}${titles.length>60?`<p class="small dim">…and ${titles.length-60} more.</p>`:''}</div></div>
  <div><div class="panel"><div class="h3"><span>Rivals</span><small>most meetings, all years · head to head</small></div><div class="board">${rivals.map(([o,w,l],i)=>`<button type="button" class="bar" data-duel="${esc(id)}|${esc(o)}" style="--i:${i};--team:${pcolor(o)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(pname(o))}<small> ${esc(natName(pnat(o)))}</small></span><small>${w+l} meetings</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*w/Math.max(1,w+l))}%"></span></span></span><span class="val">${w}–${l}</span></button>`).join('')||'<p class="muted small">Fewer than three meetings with anyone on record.</p>'}</div></div>
  ${surf.length?`<div class="panel" style="margin-top:14px"><div class="h3"><span>By surface</span><small>matches won–lost</small></div><div class="board">${surf.map(([s,w,l],i)=>`<div class="bar" style="--i:${i};--team:${surfColor(s.split(' ')[0])}"><span class="rk"></span><span><span class="lab"><span>${s}</span><small>${pct(w,w+l)}% won</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*w/Math.max(1,w+l))}%"></span></span></span><span class="val">${w}–${l}</span></div>`).join('')}</div></div>`:''}</div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Season by season</span><small>${rows.length} player-seasons in the lens</small></div><div class="tablewrap"><table><tr><th>Year</th><th>Draw</th><th class="n">W</th><th class="n">L</th><th class="n">Win %</th><th class="n">Titles</th><th class="n">Finals</th><th class="n">Majors</th><th class="n">Hard</th><th class="n">Clay</th><th class="n">Grass</th></tr>${rows.map(r=>`<tr><td><a href="#" data-year="${r.y}">${r.y}</a></td><td>${esc(r.c==='MS'?'ATP':r.c==='WS'?'WTA':r.c==='MD'?'ATP doubles':'WTA doubles')}</td><td class="n">${r.w}</td><td class="n">${r.l}</td><td class="n">${r.w+r.l?pct(r.w,r.w+r.l):'—'}</td><td class="n"><b>${r.t}</b></td><td class="n">${r.f}</td><td class="n">${r.mj}</td><td class="n">${r.hw}–${r.hl}</td><td class="n">${r.cw}–${r.cl}</td><td class="n">${r.gw}–${r.gl}</td></tr>`).join('')}</table></div></div>`;}

/* ---------- Nations ---------- */
function nationsView(){const list=natAgg();const lens=state.lens;let rows=list.filter(a=>a.id&&a.id!=='UNK');if(lens==='rate')rows=rows.filter(a=>a.p>=200);rows.sort((a,b)=>b[lens]-a[lens]||b.t-a.t||b.w-a.w);rows=rows.slice(0,40);const max=Math.max(1,...rows.map(a=>a[lens]));
  const q=(state.find2||'').toLowerCase();const found=q?list.filter(a=>natName(a.id).toLowerCase().includes(q)||a.id.toLowerCase()===q).slice(0,12):[];
  $('#view').innerHTML=`<div class="sect-head" style="margin-top:22px"><div><h2 style="font-size:24px;margin:0">Nations · ${esc(eraLabel())}</h2></div><div class="small mono muted">${list.length} nations</div></div><div class="panel"><div class="tools" style="margin-bottom:14px"><input type="search" id="find2" placeholder="Search a nation" value="${esc(state.find2||'')}" aria-label="Search"><select id="lens" aria-label="Lens">${Object.entries(LENSES).map(([k,v])=>`<option value="${k}" ${k===lens?'selected':''}>${v[0]}</option>`).join('')}</select><span class="small muted">${esc(LENSES[lens][1])}</span></div>${q?`<div class="chiplist" style="margin-bottom:14px">${found.map(a=>`<button type="button" class="chip" data-nation="${esc(a.id)}"><i style="--c:${natColor(a.id)}"></i>${esc(natName(a.id))}</button>`).join('')||'<span class="muted small">No match.</span>'}</div>`:''}
  ${natBars(rows,a=>a[lens],a=>`${a.np} players · ${a.first}–${a.last}`,max,/rate/.test(lens)?'%':'')}</div>`;
  $('#find2').addEventListener('input',e=>{state.find2=e.target.value;nationsView();$('#find2').focus();const v=$('#find2');v.setSelectionRange(v.value.length,v.value.length);});$('#lens').addEventListener('change',e=>{state.lens=e.target.value;render();});}
function nationView(id){const all=natAgg();const a=all.find(x=>x.id===id);if(!a){nationsView();return;}const rank=[...all].sort((x,y)=>y.t-x.t||y.mj-x.mj).findIndex(x=>x.id===id)+1;
  const players=playerAgg().filter(p=>p.nat===id).sort(playerOrder);const [y0,y1]=eraRange();const majors=CHAMPS.filter(c=>inLens(c.c)&&c.y>=y0&&c.y<=y1&&MAJORS.includes(c.t)&&c.w.some(p=>pnat(p)===id)).sort((x,y)=>y.y-x.y);
  const byYearT={};for(const r of psRows()){if(pnat(r.p)!==id)continue;const b=byYearT[r.y]||(byYearT[r.y]={y:r.y,t:0,w:0,l:0,mj:0});b.t+=r.t;b.w+=r.w;b.l+=r.l;b.mj+=r.mj;}
  const years=Object.values(byYearT).sort((x,y)=>x.y-y.y);const maxT=Math.max(1,...years.map(x=>x.t));
  const kpi=(t,v,s)=>`<div class="kpi"><span>${t}</span><b>${v}</b>${s?`<small>${s}</small>`:''}</div>`;
  $('#view').innerHTML=`<div class="card" style="margin-top:20px;grid-template-columns:1fr;--team:${natColor(id)}"><div class="panel" style="display:flex;flex-wrap:wrap;gap:20px;align-items:flex-end;justify-content:space-between"><div><p class="eyebrow">Nation · ${esc(id)} · ${a.first}–${a.last}</p><h2 style="margin:6px 0 0"><i class="dot" style="--c:${natColor(id)};width:.5em;height:.5em;vertical-align:.1em;margin-right:8px"></i>${esc(natName(id))}</h2></div><div class="small mono muted">#${rank} by titles in ${esc(eraLabel())}</div></div></div>
  <div class="kpis" style="margin-top:16px">${kpi('Titles',fmt(a.t),`${a.nw} different winners`)}${kpi('Majors',a.mj,'')}${kpi('Finals',fmt(a.f),'')}${kpi('Matches',`${fmt(a.w)}–${fmt(a.l)}`,a.p?a.rate+'% won':'')}${kpi('Players',fmt(a.np),'in the lens')}</div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Players</span><small>by titles, then majors</small></div>${playerBars(players.slice(0,15),p=>p.t,p=>`${p.mj} majors · ${p.f} finals · ${p.w}–${p.l} · ${p.first}–${p.last}`,Math.max(1,...players.slice(0,15).map(p=>p.t)))}</div>
  <div><div class="panel"><div class="h3"><span>Titles by year</span><small>${years.length} seasons</small></div><div class="yearbars">${years.map(x=>`<button type="button" data-year="${x.y}" title="${x.y} · ${x.t} titles · ${x.w}–${x.l}" style="--h:${Math.round(100*x.t/maxT)}%;--team:${natColor(id)}"><i></i><span>${x.y%10===0?x.y:''}</span></button>`).join('')}</div></div>
  <div class="panel" style="margin-top:14px"><div class="h3"><span>Majors</span><small>${majors.length} titles</small></div><div class="board">${majors.slice(0,30).map((c,i)=>`<button type="button" class="bar" data-edition="${esc(c.id)}" data-year="${c.y}" style="--i:${i};--team:${pcolor(c.w[0])}"><span class="rk">${majors.length-i}</span><span><span class="lab"><span>${esc(pnames(c.w))}<small> ${esc(TOURN[c.t]?.n||c.t)} ${c.y}</small></span><small>d. ${esc(pnames(c.l))||'—'}${c.s?' · '+esc(c.s):''}</small></span></span></button>`).join('')||'<p class="muted small">No major titles in this lens.</p>'}</div></div></div></div>`;}

/* ---------- Tournaments ---------- */
function tournamentsView(){const list=courtModel().sort((a,b)=>(b.major-a.major)||b.count-a.count||a.name.localeCompare(b.name));const q=(state.find2||'').toLowerCase();const rows=q?list.filter(c=>(c.name+' '+c.place).toLowerCase().includes(q)):list;
  $('#view').innerHTML=`<div class="sect-head" style="margin-top:22px"><div><h2 style="font-size:24px;margin:0">Tournaments · ${esc(eraLabel())}</h2></div><div class="small mono muted">${list.length} events</div></div><div class="panel"><div class="tools" style="margin-bottom:14px"><input type="search" id="find2" placeholder="Search a tournament or city" value="${esc(state.find2||'')}" aria-label="Search"></div><div class="tablewrap" style="max-height:640px"><table><tr><th>Tournament</th><th>City</th><th>Surface</th><th>Level</th><th class="n">Editions</th><th>Years</th><th>Most titles</th></tr>${rows.slice(0,400).map(c=>`<tr><td><a href="#" data-tourn="${esc(c.cid)}">${esc(c.name)}</a>${c.major?' <span class="dim">★</span>':''}</td><td>${esc(c.place)}</td><td><i class="dot" style="--c:${surfColor(c.surface)}"></i>${esc(c.surface)}</td><td>${esc(levelName(c.lv))}</td><td class="n">${c.count}</td><td>${c.first}–${c.last}</td><td>${c.top?flag(c.top)+' '+pl(c.top)+' <span class="dim">'+c.topN+'</span>':'—'}</td></tr>`).join('')}</table></div>${rows.length>400?`<p class="small dim">Showing 400 of ${rows.length}; search to narrow.</p>`:''}</div>`;
  $('#find2').addEventListener('input',e=>{state.find2=e.target.value;tournamentsView();$('#find2').focus();const v=$('#find2');v.setSelectionRange(v.value.length,v.value.length);});}
function tournamentView(id){const t=TOURN[id];if(!t){tournamentsView();return;}const [y0,y1]=eraRange();const eds=Object.values(EDS).filter(e=>e.t===id&&inLens(e.c)&&e.y>=y0&&e.y<=y1).sort((a,b)=>b.y-a.y||(a.date<b.date?1:-1));
  const roll=CHAMPS.filter(c=>c.t===id&&inLens(c.c)&&c.y>=y0&&c.y<=y1).sort((a,b)=>b.y-a.y||a.c.localeCompare(b.c));const wins={};for(const c of roll)for(const p of c.w)wins[p]=(wins[p]||0)+1;const top=Object.entries(wins).sort((a,b)=>b[1]-a[1]).slice(0,10);
  const surfs={};for(const e of eds)surfs[e.surface]=(surfs[e.surface]||0)+1;const surf=Object.entries(surfs).sort((a,b)=>b[1]-a[1]);const kpi=(k,v,s)=>`<div class="kpi"><span>${k}</span><b>${v}</b>${s?`<small>${s}</small>`:''}</div>`;
  const first=Math.min(...roll.map(c=>c.y),...eds.map(e=>e.y)),last=Math.max(...roll.map(c=>c.y),...eds.map(e=>e.y));
  $('#view').innerHTML=`<div class="card" style="margin-top:20px;grid-template-columns:1fr;--team:${surfColor(surf[0]?.[0]||t.s||'Unknown')}"><div class="panel" style="display:flex;flex-wrap:wrap;gap:20px;align-items:flex-end;justify-content:space-between"><div><p class="eyebrow">Tournament${t.major?' · major':''} · ${esc((t.city||'').split(' · ').join(', '))}${surf.length?' · '+surf.map(([s,n])=>esc(s)+(surf.length>1?' '+n:'')).join(', '):t.s?' · '+esc(t.s):''}</p><h2 style="margin:6px 0 0">${esc(t.n)}</h2></div>${t.url?`<a class="small mono" href="${esc(t.url)}" target="_blank" rel="noopener" style="color:var(--muted)">official site ↗</a>`:''}</div></div>
  <div class="kpis" style="margin-top:16px">${kpi('Editions',eds.length||roll.length,isFinite(first)?`${first}–${last}`:'')}${kpi('Titles recorded',roll.length,'in the lens')}${kpi('Most titles',top[0]?pname(top[0][0]):'—',top[0]?top[0][1]+' titles':'')}${kpi('Different champions',Object.keys(wins).length,'')}</div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Roll of honour</span><small>${roll.length} titles · click a year to open its draw</small></div><div class="tablewrap" style="max-height:640px"><table><tr><th>Year</th><th>Draw</th><th>Champion</th><th>Runner-up</th><th>Score</th></tr>${roll.map(c=>`<tr><td>${EDS[c.id]?`<a href="#" data-edition="${esc(c.id)}" data-year="${c.y}">${c.y}</a>`:c.y}</td><td>${esc(c.c==='MS'?'ATP':c.c==='WS'?'WTA':c.c==='MD'?'ATP doubles':c.c==='WD'?'WTA doubles':c.c)}</td><td>${(c.w||[]).map(p=>flag(p)+' '+pl(p)).join(' / ')}</td><td>${(c.l||[]).map(p=>pl(p)).join(' / ')||'—'}</td><td class="mono small">${esc(c.s||'')}</td></tr>`).join('')}</table></div></div>
  <div class="panel"><div class="h3"><span>Most titles here</span></div>${playerBars(top.map(([id,n])=>({id,n})),a=>a.n,a=>`${roll.filter(c=>c.w.includes(a.id)).map(c=>c.y).sort().join(', ')}`,top[0]?top[0][1]:1)}</div></div>`;}

/* ---------- Records ---------- */
function recordsView(){const players=playerAgg();const nations=natAgg().filter(a=>a.id&&a.id!=='UNK');const [y0,y1]=eraRange();const titles=eraTitles();const eds=eraEditions().filter(e=>!e.team&&e.level!=='D');const matches=eraSeasons().reduce((a,s)=>a+s.matches,0);
  const kpi=(t,v,s)=>`<div class="kpi"><span>${t}</span><b>${v}</b><small>${s}</small></div>`;const rc=(k,l)=>[...players].filter(p=>k==='rate'?p.p>=100:true).sort((a,b)=>b[k]-a[k]||b.t-a.t).slice(0,10);
  const board=(title,rows,k,unit='')=>`<div class="panel"><div class="h3"><span>${title}</span></div>${playerBars(rows,a=>a[k],a=>`${a.first}–${a.last} · ${a.t} titles · ${a.mj} majors`,Math.max(1,...rows.map(a=>a[k])),unit)}</div>`;
  const recs=[];for(const c of circs()){const R=RECORDS[c]||{};for(const k in R)for(const r of R[k])if(r[2]>=y0&&r[2]<=y1)recs.push({k,c,r});}
  const rlist=(k,title,valOf,unit)=>{const rows=recs.filter(x=>x.k===k).sort((a,b)=>b.r[0]-a.r[0]).slice(0,8);return rows.length?`<div class="panel"><div class="h3"><span>${title}</span><small>${unit}</small></div><div class="board">${rows.map(({r},i)=>{const eid=r[1].replace(/:\d+$/,'');const e=EDS[eid];return `<button type="button" class="bar" data-edition="${esc(eid)}" data-match="${esc(r[1])}" data-year="${r[2]}" style="--i:${i};--team:${pcolor(k==='aces'?r[7]:r[3])}"><span class="rk">${i+1}</span><span><span class="lab"><span>${k==='aces'?esc(pname(r[7])):esc(pname(r[3]))+'<small> d. '+esc(pname(r[4]))+'</small>'}${k==='aces'?'<small> v '+esc(pname(r[7]===r[3]?r[4]:r[3]))+'</small>':''}</span><small>${esc(e?edName(e):eid)} ${r[2]} · ${esc(roundName[r[6]]||r[6])}${k==='upsets'?' · rank '+r[7]+' beat rank '+r[8]:''} · ${esc(r[5])}</small></span></span><span class="val">${valOf(r)}</span></button>`;}).join('')}</div></div>`:'';};
  const mj=CHAMPS.filter(c=>inLens(c.c)&&c.y>=y0&&c.y<=y1&&MAJORS.includes(c.t)&&c.w.length===1&&PLAYERS[c.w[0]]?.dob).map(c=>({c,a:age(PLAYERS[c.w[0]].dob,EDS[c.id]?.date||c.y+'-07-01')})).filter(x=>x.a!=null);const young=[...mj].sort((a,b)=>a.a-b.a).slice(0,6),old=[...mj].sort((a,b)=>b.a-a.a).slice(0,6);
  const ages=(title,rows)=>rows.length?`<div class="panel"><div class="h3"><span>${title}</span><small>at the final, from recorded birth dates</small></div><div class="board">${rows.map(({c,a},i)=>`<button type="button" class="bar" data-edition="${esc(c.id)}" data-year="${c.y}" style="--i:${i};--team:${pcolor(c.w[0])}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(pname(c.w[0]))}<small> ${esc(TOURN[c.t]?.n||c.t)} ${c.y}</small></span></span></span><span class="val">${a}</span></button>`).join('')}</div></div>`:'';
  $('#view').innerHTML=`<div class="sect-head" style="margin-top:22px"><div><h2 style="font-size:24px;margin:0">Records · ${esc(eraLabel())}</h2></div><div class="small mono muted">${fmt(titles.length)} titles</div></div>
  <div class="kpis">${kpi('Titles',fmt(titles.length),`${fmt(eds.length)} tournaments`)}${kpi('Matches',fmt(matches),matches?'recorded from 1968':'no match records before 1968')}${kpi('Players',fmt(players.length),`${fmt(players.filter(p=>p.t).length)} won a title`)}${kpi('Nations',nations.length,`${nations.filter(n=>n.t).length} with a title`)}${kpi('Majors',fmt(titles.filter(c=>MAJORS.includes(c.t)).length),'')}</div>
  <div class="three" style="margin-top:20px">${board('Titles',rc('t'),'t')}${board('Majors',rc('mj'),'mj')}${board('Finals',rc('f'),'f')}</div>
  <div class="three" style="margin-top:14px">${board('Match wins',rc('w'),'w')}${board('Win rate · 100+ matches',rc('rate'),'rate','%')}<div class="panel"><div class="h3"><span>Nations by titles</span></div>${natBars([...nations].sort((a,b)=>b.t-a.t).slice(0,10),a=>a.t,a=>`${a.np} players`,Math.max(1,...nations.map(a=>a.t)))}</div></div>
  <div class="three" style="margin-top:14px">${rlist('longest','Longest matches',r=>Math.floor(r[0]/60)+'h '+String(r[0]%60).padStart(2,'0'),'recorded duration')}${rlist('aces','Most aces in a match',r=>r[0],'serve statistics from 1991')}${rlist('games','Most games in a match',r=>r[0],'games played')}</div>
  <div class="three" style="margin-top:14px">${rlist('upsets','Biggest upsets by ranking',r=>r[7],'winner’s rank · top-three seeds beaten')}${ages('Youngest major champions',young)}${ages('Oldest major champions',old)}</div>`;}

/* ---------- Barcode ---------- */
const HEATMETRICS={t:['Titles','Titles won by the nation’s players that year.'],mj:['Majors','Grand Slam titles that year.'],w:['Match wins','Matches won that year (from 1968).'],rate:['Win rate %','Wins divided by matches that year; blank below 20 matches.']};
function barcodeView(){const ss=eraSeasons();const years=ss.map(s=>s.year);const cell={};const tot={};
  for(const r of psRows()){const n=pnat(r.p);if(!n||n==='UNK')continue;const c=cell[n]||(cell[n]={});const k=c[r.y]||(c[r.y]={t:0,mj:0,w:0,l:0});k.t+=r.t;k.mj+=r.mj;k.w+=r.w;k.l+=r.l;tot[n]=(tot[n]||0)+(state.heat==='w'||state.heat==='rate'?r.w:state.heat==='mj'?r.mj:r.t);}
  const nations=Object.keys(cell).sort((a,b)=>tot[b]-tot[a]).slice(0,28);const val=k=>!k?0:state.heat==='rate'?(k.w+k.l>=20?pct(k.w,k.w+k.l):0):k[state.heat];const max=Math.max(1,...nations.flatMap(n=>years.map(y=>val(cell[n][y]))));
  $('#view').innerHTML=`<div class="sect-head" style="margin-top:22px"><div><h2 style="font-size:24px;margin:0">Season barcode · ${esc(eraLabel())}</h2></div><div class="small mono muted">${nations.length} nations × ${years.length} seasons</div></div><div class="panel"><div class="tools" style="margin-bottom:14px"><select id="heat" aria-label="Metric">${Object.entries(HEATMETRICS).map(([k,v])=>`<option value="${k}" ${k===state.heat?'selected':''}>${v[0]}</option>`).join('')}</select><span class="small muted">${esc(HEATMETRICS[state.heat][1])} Brightness is the cell’s share of the brightest cell; colour is the nation’s. Rows ordered by total.</span></div>
  <div class="barcode"><div class="bc-row"><span></span><span class="cells" style="gap:2px">${years.map(y=>`<i style="background:none;height:14px;font-size:8px;color:var(--dim);text-align:center;line-height:14px">${years.length<=30||y%10===0?String(y).slice(2):''}</i>`).join('')}</span><span></span></div>${nations.map(n=>`<div class="bc-row"><span class="lab" data-nation="${esc(n)}">${esc(natName(n))}</span><span class="cells">${years.map(y=>{const v=val(cell[n][y]);const a=v?Math.max(.12,v/max):0;return `<i data-year="${y}" title="${esc(natName(n))} ${y} · ${v}${state.heat==='rate'?'%':''}" style="--c:${mixHex(natColor(n),'#0f1113',a)}"></i>`;}).join('')}</span><span class="tot">${fmt(Math.round(tot[n]))}</span></div>`).join('')}</div></div>`;
  $('#heat').addEventListener('change',e=>{state.heat=e.target.value;render();});}

/* ---------- Duel ---------- */
function swingChart(el,pts,labA,labB,cA,cB){const box=el.getBoundingClientRect(),W=Math.max(300,box.width),H=Math.max(180,box.height);const padL=30,padR=30,padT=16,padB=22;const n=pts.length;const max=Math.max(1,...pts.map(p=>Math.abs(p.v)));const x=i=>padL+(n>1?i*(W-padL-padR)/(n-1):(W-padL-padR)/2),y=v=>padT+(H-padT-padB)*(1-(v+max)/(2*max));
  const mid=y(0);let d='';pts.forEach((p,i)=>{d+=(i?'L':'M')+x(i).toFixed(1)+' '+y(p.v).toFixed(1);});
  const dots=pts.map((p,i)=>`<circle class="pt" cx="${x(i).toFixed(1)}" cy="${y(p.v).toFixed(1)}" r="4" fill="${p.win==='A'?cA:cB}" data-edition="${esc(p.e||'')}" data-year="${p.y||''}" data-match="${esc(p.m||'')}"><title>${esc(p.label)}</title></circle>`).join('');
  el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Head-to-head swing"><line class="gridl" x1="${padL}" x2="${W-padR}" y1="${mid.toFixed(1)}" y2="${mid.toFixed(1)}"/><text class="lb" x="${padL}" y="${padT-4}" style="fill:${cA}">${esc(labA)} ahead</text><text class="lb" x="${padL}" y="${H-6}" style="fill:${cB}">${esc(labB)} ahead</text><path class="ser" d="${d}" style="--c:var(--muted)"/>${dots}</svg>`;}
let duelLoad=null;
function duelView(){const players=playerAgg().sort(playerOrder);const nations=natAgg().filter(a=>a.id&&a.id!=='UNK').sort((a,b)=>b.t-a.t);
  if(state.duelBy==='p'){const ids=players.slice(0,120).map(p=>p.id);if(!state.dA||!PLAYERS[state.dA]){let best=null;for(const id of ids.slice(0,20))for(const [o,w,l] of RIVALS[id]||[]){if(ids.includes(o)&&(!best||w+l>best.n))best={a:id,b:o,n:w+l};}state.dA=best?best.a:ids[0];state.dB=best?best.b:null;}if(!state.dB||!PLAYERS[state.dB]||state.dB===state.dA){const r=(RIVALS[state.dA]||[]).find(x=>PLAYERS[x[0]]);state.dB=r?r[0]:ids.find(i=>i!==state.dA);}}
  else{const ids=nations.slice(0,60).map(n=>n.id);if(!state.dA||!ids.includes(state.dA))state.dA=ids[0];if(!state.dB||!ids.includes(state.dB)||state.dB===state.dA)state.dB=ids.find(i=>i!==state.dA);}
  const opts=(sel)=>state.duelBy==='p'?[...new Set([state.dA,state.dB,...players.slice(0,120).map(p=>p.id)])].filter(Boolean).map(id=>`<option value="${esc(id)}" ${id===sel?'selected':''}>${esc(pname(id))}</option>`).join(''):nations.slice(0,60).map(n=>`<option value="${esc(n.id)}" ${n.id===sel?'selected':''}>${esc(natName(n.id))}</option>`).join('');
  const head=`<div class="sect-head" style="margin-top:22px"><div><h2 style="font-size:24px;margin:0">Head to head · ${esc(eraLabel())}</h2></div><div class="small mono muted">${state.duelBy==='p'?'players · every meeting on record':'nations · titles and wins in the lens'}</div></div><div class="panel"><div class="tools" style="margin-bottom:14px"><select id="duelBy" aria-label="Compare"><option value="p" ${state.duelBy==='p'?'selected':''}>Players</option><option value="n" ${state.duelBy==='n'?'selected':''}>Nations</option></select><select id="dA" aria-label="First">${opts(state.dA)}</select><span class="mono small muted">vs</span><select id="dB" aria-label="Second">${opts(state.dB)}</select></div><div id="duelBody"></div></div>`;
  $('#view').innerHTML=head;$('#duelBy').addEventListener('change',e=>{state.duelBy=e.target.value;state.dA=null;state.dB=null;render();});$('#dA').addEventListener('change',e=>{state.dA=e.target.value;render();});$('#dB').addEventListener('change',e=>{state.dB=e.target.value;render();});
  if(state.duelBy==='n')duelNations(nations);else duelPlayers();}
function duelNations(nations){const NA=nations.find(n=>n.id===state.dA),NB=nations.find(n=>n.id===state.dB);if(!NA||!NB){$('#duelBody').innerHTML='<p class="muted">Pick two nations.</p>';return;}const cA=natColor(NA.id),cB=natColor(NB.id);
  const by={};for(const r of psRows()){const n=pnat(r.p);if(n!==NA.id&&n!==NB.id)continue;const b=by[r.y]||(by[r.y]={y:r.y,a:0,b:0,aw:0,bw:0});if(n===NA.id){b.a+=r.t;b.aw+=r.w;}else{b.b+=r.t;b.bw+=r.w;}}
  const years=Object.values(by).sort((x,y)=>x.y-y.y);let lead=0;const pts=years.map(x=>{lead+=x.a-x.b;return {v:lead,win:x.a>=x.b?'A':'B',y:x.y,label:`${x.y} · ${natName(NA.id)} ${x.a} titles · ${natName(NB.id)} ${x.b} titles`};});
  const rowsK=[['Titles','t'],['Majors','mj'],['Finals','f'],['Match wins','w'],['Win rate %','rate'],['Players','np'],['Title winners','nw']];
  $('#duelBody').innerHTML=`<div class="duel-heads"><div class="dh" style="--team:${cA}"><span class="eyebrow">${esc(natName(NA.id))}</span><b>${fmt(NA.t)}</b><small>titles · ${NA.mj} majors</small></div><div class="dh" style="--team:${cB}"><span class="eyebrow">${esc(natName(NB.id))}</span><b>${fmt(NB.t)}</b><small>titles · ${NB.mj} majors</small></div></div><div class="h3" style="margin-top:18px"><span>The lead in titles, year by year</span><small>cumulative</small></div><div class="chart" id="duelSwing" style="height:220px"></div>
  <div class="tablewrap" style="margin-top:14px"><table><tr><th style="text-align:right;color:${cA}">${esc(natName(NA.id))}</th><th style="text-align:center"></th><th style="color:${cB}">${esc(natName(NB.id))}</th></tr>${rowsK.map(([l,k])=>{const va=NA[k],vb=NB[k];const m=Math.max(va,vb,1);return `<tr><td style="text-align:right"><span style="display:inline-block;height:8px;width:${Math.round(120*va/m)}px;background:${cA};border-radius:2px;vertical-align:middle;margin-right:8px"></span><b>${fmt(va)}${/rate/.test(k)?'%':''}</b></td><td style="text-align:center;color:var(--muted);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase">${l}</td><td><b>${fmt(vb)}${/rate/.test(k)?'%':''}</b><span style="display:inline-block;height:8px;width:${Math.round(120*vb/m)}px;background:${cB};border-radius:2px;vertical-align:middle;margin-left:8px"></span></td></tr>`;}).join('')}</table></div>`;
  if(pts.length)swingChart($('#duelSwing'),pts,natName(NA.id),natName(NB.id),cA,cB);}
function duelPlayers(){const a=state.dA,b=state.dB;if(!a||!b){$('#duelBody').innerHTML='<p class="muted">Pick two players.</p>';return;}const cA=pcolor(a),cB=pcolor(b);
  const yearsA=new Set(PS.filter(r=>r.p===a).map(r=>r.y)),yearsB=new Set(PS.filter(r=>r.p===b).map(r=>r.y));const years=(A.matchYears||[]).filter(y=>yearsA.has(y)&&yearsB.has(y));const missing=years.filter(y=>!DETAILS[y]);
  const meetings=[];for(const y of years){const d=DETAILS[y];if(!d)continue;for(const eid in d){const e=EDS[eid];if(!e||!['MS','WS'].includes(e.c))continue;for(const row of d[eid]){const m=unpack(MF,row);if(m.w.length!==1||m.l.length!==1)continue;if((m.w[0]===a&&m.l[0]===b)||(m.w[0]===b&&m.l[0]===a))meetings.push({m,e});}}}
  meetings.sort((x,y)=>x.e.date<y.e.date?-1:x.e.date>y.e.date?1:(x.m.n||0)-(y.m.n||0));
  const wa=meetings.filter(x=>x.m.w[0]===a).length,wb=meetings.length-wa;const surf={};for(const x of meetings){const s=surf[x.e.surface]||(surf[x.e.surface]={a:0,b:0});if(x.m.w[0]===a)s.a++;else s.b++;}
  let lead=0;const pts=meetings.map(x=>{lead+=x.m.w[0]===a?1:-1;return {v:lead,win:x.m.w[0]===a?'A':'B',e:x.e.id,y:x.e.y,m:x.m.id,label:`${edName(x.e)} ${x.e.y} · ${roundName[x.m.r]||x.m.r} · ${pname(x.m.w[0])} ${x.m.s}`};});
  const status=missing.length?`<p class="small muted" id="duelStatus">Loading the seasons the two shared · ${years.length-missing.length} of ${years.length}…</p>`:'';
  $('#duelBody').innerHTML=`<div class="duel-heads"><div class="dh" style="--team:${cA}"><span class="eyebrow">${esc(natName(pnat(a)))}</span><b>${wa}</b><small>${pl(a)} · wins in ${meetings.length} meetings</small></div><div class="dh" style="--team:${cB}"><span class="eyebrow">${esc(natName(pnat(b)))}</span><b>${wb}</b><small>${pl(b)}</small></div></div>${status}
  ${meetings.length?`<div class="h3" style="margin-top:18px"><span>The rivalry, match by match</span><small>cumulative lead · click a point to open the match</small></div><div class="chart" id="duelSwing" style="height:220px"></div><div class="chiplist" style="margin-top:12px">${Object.entries(surf).map(([s,v])=>`<span class="chip" style="cursor:default"><i style="--c:${surfColor(s)}"></i>${esc(s)} ${v.a}–${v.b}</span>`).join('')}</div>
  <div class="tablewrap" style="margin-top:14px;max-height:520px"><table><tr><th>Year</th><th>Tournament</th><th>Round</th><th>Surface</th><th>Winner</th><th>Score</th></tr>${[...meetings].reverse().map(({m,e})=>`<tr><td><a href="#" data-edition="${esc(e.id)}" data-year="${e.y}" data-match="${esc(m.id)}">${e.y}</a></td><td>${esc(edName(e))}</td><td>${esc(roundName[m.r]||m.r)}</td><td><i class="dot" style="--c:${surfColor(e.surface)}"></i>${esc(e.surface)}</td><td style="color:${m.w[0]===a?cA:cB}"><b>${esc(pname(m.w[0]))}</b></td><td class="mono small">${esc(m.s||'')}</td></tr>`).join('')}</table></div>`:missing.length?'':'<p class="muted small" style="margin-top:14px">No tour-level meetings on record between these two.</p>'}`;
  if(pts.length)swingChart($('#duelSwing'),pts,pname(a),pname(b),cA,cB);
  if(missing.length&&DETAIL_URL){const token=duelLoad={a,b};(async()=>{let k=years.length-missing.length;for(const y of missing){if(duelLoad!==token||state.tab!=='duel')return;await loadDetails(y);k++;const st=$('#duelStatus');if(st)st.textContent=`Loading the seasons the two shared · ${k} of ${years.length}…`;}if(duelLoad===token&&state.tab==='duel'&&state.dA===a&&state.dB===b)duelPlayers();})();}}

/* ---------- Sources & coverage ---------- */
function drawSources(){const kpi=(t,v,s)=>`<div class="kpi"><span>${t}</span><b>${v}</b><small>${s}</small></div>`;const cov=A.coverage||{};const scope=cov.scope||[];
  $('#sourcesBody').innerHTML=`<p class="eyebrow">Tour edition / ${esc(day(A.snapshot))}</p><h2>Every title, every match of the Open era, one archive.</h2><div class="kpis">${kpi('Matches',fmt(cov.matches),'tour-level, 1968 on')}${kpi('Titles',fmt(cov.titles),'majors from 1877')}${kpi('Players',fmt(cov.players),'')}${kpi('Tournaments',fmt(cov.tournaments),`${fmt(cov.editions)} editions`)}${kpi('With statistics',fmt(cov.statistics),'serve statistics, 1991 on')}${kpi('Latest event',esc(day(A.lastDate)),'snapshot '+esc(day(A.snapshot)))}</div>
<h3>Sources</h3><ol><li><a href="https://github.com/JeffSackmann" target="_blank" rel="noopener">Jeff Sackmann / Tennis Abstract</a> (<a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noopener">CC BY-NC-SA 4.0</a>)<p>The tour-level match results of the ATP and WTA from 1968 (${scope.map(s=>`${s.c==='MS'?'ATP singles':s.c==='WS'?'WTA singles':s.c==='MD'?'ATP doubles':s.c==='WD'?'WTA doubles':s.c} ${s.start||'—'}–${s.end||'—'}, ${fmt(s.matches)} matches`).join('; ')}), with seedings, rankings, durations and serve statistics where recorded. Source commit ${esc((A.sourceCommit||'').slice(0,10))}. This atlas is non-commercial and shares alike.</p></li><li>Wimbledon’s own records<p>Champions and finalists before 1968 from the Wimbledon Compendium, the club’s published roll of honour from 1877 (singles from 1877 and 1884, doubles from 1884 and 1913), used as facts. The other majors’ rolls begin with the Open era in this archive.</p></li></ol>
<h3>How to read the statistics</h3><p class="small muted">A title is a tournament won at tour level as the source records it; team ties (Davis Cup, Billie Jean King Cup) are kept off the grid and out of the title counts. The River shares each year’s titles among the winners’ nations, a doubles title split between partners. “Most titles of the year” ranks by titles, then majors, then finals, then match wins; it is a reading of the roll of honour, not a ranking or an award. Match records begin with the Open era, so wins, win rates and head-to-heads are 1968 onward; serve statistics exist from 1991 and thinly before the 2000s. Win rate needs 100 matches for a player and 200 for a nation. Nationalities are as the source lists them today, so historical nations (the Soviet Union, Czechoslovakia, West Germany) appear only where the source keeps them. Ages are computed from recorded birth dates.</p>`;}

/* ---------- deep links ---------- */
let routeLock=false;
function writeRoute(){if(routeLock)return;const q=[];if(state.tour!=='M')q.push('tour='+state.tour);if(state.disc!=='S')q.push('draw=D');if(state.era!=='all')q.push('era='+encodeURIComponent(state.era));if(state.whole)q.push('whole=1');else q.push('season='+state.year);q.push('tab='+state.tab);if(state.tab==='draw'&&!state.whole&&state.edition)q.push('edition='+encodeURIComponent(state.edition));if(state.tab==='draw'&&!state.whole&&state.match)q.push('match='+encodeURIComponent(state.match));for(const k of ['nation','player','tourn']){if(state.tab===(k==='tourn'?'tournaments':k+'s')&&state[k])q.push(k+'='+encodeURIComponent(state[k]));}if(state.tab==='duel'&&state.dA&&state.dB)q.push('duel='+encodeURIComponent(state.dA+'|'+state.dB)+'&by='+state.duelBy);const h='#'+q.join('&');if(location.hash!==h){try{history.replaceState(null,'',h);}catch(e){}}}
function readRoute(){const h=location.hash.replace(/^#\/?/,'');if(!h||/^static-/.test(h))return false;const p={};for(const kv of h.split('&')){const i=kv.indexOf('=');p[i<0?kv:kv.slice(0,i)]=i<0?'1':decodeURIComponent(kv.slice(i+1));}let any=false;
  if(['M','W','all'].includes(p.tour)){state.tour=p.tour;any=true;}if(p.draw==='D'||p.draw==='S'){state.disc=p.draw;any=true;}rebuildSeasons();
  if(p.era&&(p.era==='all'||ERAS.some(e=>e.id===p.era))){state.era=p.era;any=true;}
  if(p.edition&&EDS[p.edition]){const e=EDS[p.edition];if(!inLens(e.c)){state.tour=e.c[0];state.disc=e.c[1];rebuildSeasons();}state.edition=p.edition;state.year=e.y;any=true;}else if(p.season&&byYear[+p.season]){state.year=+p.season;any=true;}
  if(p.match)state.match=p.match;
  if(state.era!=='all'&&!inEraYear(state.year)){if(p.season||p.edition)state.era='all';else state.year=eraSeasons().slice(-1)[0]?.year||state.year;}
  state.whole=p.whole==='1';if(state.whole)any=true;
  if(p.tab&&TABS.some(t=>t[0]===p.tab)){state.tab=p.tab;any=true;}
  state.nation=p.nation&&IOC[p.nation]!==undefined?p.nation:null;state.player=p.player&&PLAYERS[p.player]?p.player:null;state.tourn=p.tourn&&TOURN[p.tourn]?p.tourn:null;
  if(p.duel){const [a,b]=p.duel.split('|');state.duelBy=p.by==='n'?'n':'p';state.dA=a;state.dB=b;any=true;}
  return any;}

/* ---------- render, navigation, events ---------- */
function render(){stopReplay();drawTabs();if(tour.stopped||!tour.timer)drawEraStrip();const v={season:seasonView,draw:drawView,players:()=>state.player?playerView(state.player):playersView(),nations:()=>state.nation?nationView(state.nation):nationsView(),tournaments:()=>state.tourn?tournamentView(state.tourn):tournamentsView(),records:recordsView,barcode:barcodeView,duel:duelView}[state.tab];try{v();}catch(e){$('#view').innerHTML=`<p class="muted">Something in this view could not be drawn: ${esc(e.message)}</p>`;console.error(e);}writeRoute();}
function go(tab,scroll=true){state.tab=tab;render();if(scroll)$('#stage').scrollIntoView({behavior:RM?'auto':'smooth',block:'start'});}
function ensureYearInLens(y){if(state.era!=='all'&&!inEraYear(y)){state.era='all';$('#eraSelect').value='all';drawGrid();}}
function setSeason(y,scroll){state.whole=false;ensureYearInLens(y);state.year=y;state.edition=null;state.match=null;fillSeasons();applyTheme();drawRiver();if(state.tab!=='season'&&state.tab!=='draw')state.tab='season';go(state.tab,scroll);}
function openEdition(id,scroll,match){const e=EDS[id];if(!e)return;state.whole=false;if(!inLens(e.c)){state.tour=e.c[0];state.disc=e.c[1];$('#tour').value=state.tour;$('#disc').value=state.disc;relens(false);}ensureYearInLens(e.y);state.year=e.y;state.edition=id;state.match=match||null;fillSeasons();applyTheme();drawRiver();go('draw',scroll);}
function fillSeasons(){const sel=$('#season');const ss=eraSeasons();if(!ss.length){sel.innerHTML='';return;}const e=state.era==='all'?null:ERAS.find(x=>x.id===state.era);sel.innerHTML=`<option value="era">${e?'Whole era':'All seasons'} · ${ss[0].year}–${ss[ss.length-1].year}</option>`+ss.slice().reverse().map(s=>`<option value="${s.year}">${s.year}</option>`).join('');sel.value=state.whole?'era':state.year;}
function setEra(id){tourStop();state.era=id;$('#eraSelect').value=id;if(id!=='all'){if(!inEraYear(state.year)){const last=eraSeasons().slice(-1)[0];state.year=last?last.year:state.year;state.edition=null;state.match=null;}}fillSeasons();applyTheme();drawRiver();drawGrid();render();}
function relens(rerender=true){rebuildSeasons();if(!byYear[state.year])state.year=LAST_YEAR;state.edition=null;state.match=null;state.nation=null;state.player=null;state.tourn=null;fillSeasons();$('#eraSelect').innerHTML=`<option value="all">All eras · ${FIRST_YEAR}–${LAST_YEAR}</option>`+ERAS.filter(e=>e.to>=FIRST_YEAR).map(e=>`<option value="${e.id}">${esc(ERA_SHORT[e.id]||e.name)} · ${e.from}–${e.to}</option>`).join('');$('#eraSelect').value=state.era;if(rerender){applyTheme();drawRiver();drawGrid();render();}}
function init(){
  rebuildSeasons();
  $('#eraSelect').innerHTML=`<option value="all">All eras · ${FIRST_YEAR}–${LAST_YEAR}</option>`+ERAS.map(e=>`<option value="${e.id}">${esc(ERA_SHORT[e.id]||e.name)} · ${e.from}–${e.to}</option>`).join('');
  const topNat=natAgg().sort((a,b)=>b.t-a.t).slice(0,16).map(n=>n.id);
  $('#theme').innerHTML=`<option value="champion">Champion’s colours</option><optgroup label="Surfaces">${Object.keys(SURF).filter(s=>s!=='Unknown').map(s=>`<option value="${s}">${s}</option>`).join('')}</optgroup><optgroup label="Nations">${topNat.map(n=>`<option value="${esc(n)}">${esc(natName(n))}</option>`).join('')}</optgroup>`;
  fillSeasons();
  const cov=A.coverage||{};
  $('#edition').innerHTML=`<span><span class="live"></span><b>${fmt(cov.titles||CHAMPS.length)}</b> titles through <b>${Math.max(...CHAMPS.map(c=>c.y))}</b></span><span><b>${fmt(cov.matches)}</b> matches through <b>${esc(day(A.lastDate))}</b></span><span><b>${fmt(cov.players)}</b> players</span><span><b>${fmt(cov.tournaments)}</b> tournaments</span>`;
  $('#reading').open=false;
  const deep=readRoute();if(deep){tourStop();$('#tour').value=state.tour;$('#disc').value=state.disc;$('#eraSelect').value=state.era;fillSeasons();}
  drawSources();applyTheme();drawRiver();drawGrid();render();lightsOut();if(deep&&(state.tab!=='season'||state.whole||state.era!=='all'))setTimeout(()=>$('#stage').scrollIntoView({behavior:'auto',block:'start'}),60);
  addEventListener('hashchange',()=>{if(/^#static-/.test(location.hash)){$('#reading').open=true;return;}routeLock=true;try{if(readRoute()){tourStop();$('#tour').value=state.tour;$('#disc').value=state.disc;$('#eraSelect').value=state.era;fillSeasons();applyTheme();drawRiver();drawGrid();render();}}finally{routeLock=false;}});
  $('#eraSelect').addEventListener('change',e=>setEra(e.target.value));
  $('#tour').addEventListener('change',e=>{state.tour=e.target.value;relens();});
  $('#disc').addEventListener('change',e=>{state.disc=e.target.value;relens();});
  $('#season').addEventListener('change',e=>{if(e.target.value==='era'){state.whole=true;applyTheme();drawRiver();if(state.tab!=='season'&&state.tab!=='draw')state.tab='season';go(state.tab,false);}else setSeason(+e.target.value,false);});
  $('#theme').addEventListener('change',applyTheme);
  $('#gridSort').addEventListener('change',e=>{state.gridSort=e.target.value;drawGrid();});
  $('#gridMin').addEventListener('change',e=>{state.gridMin=+e.target.value;drawGrid();});
  $('#gridFind').addEventListener('input',e=>{state.gridFind=e.target.value;drawGrid();});
  $('#eraStrip').addEventListener('click',e=>{const s=e.target.closest('[data-era]');if(s)setEra(state.era===s.dataset.era?'all':s.dataset.era);});
  $('#eraStrip').addEventListener('pointerenter',()=>{tourPause();},{passive:true});$('#eraStrip').addEventListener('pointerleave',()=>{if(!tour.stopped)tourStart();},{passive:true});
  $('#eraStrip').addEventListener('mouseover',e=>{const s=e.target.closest('[data-era]');if(s&&!tour.stopped){drawEraStrip(s.dataset.era);}});
  if('IntersectionObserver' in window){new IntersectionObserver(en=>{tour.visible=en[0].isIntersecting;if(tour.visible)tourStart();else tourPause();},{threshold:.2}).observe($('#eraStrip'));}else{tour.visible=true;tourStart();}
  $('#circuits').addEventListener('click',e=>{const b=e.target.closest('[data-cid]');if(b){state.tourn=b.dataset.cid;go('tournaments');}});
  const clear=t=>{if(t==='nations')state.nation=null;if(t==='players')state.player=null;if(t==='tournaments')state.tourn=null;};
  $('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;clear(b.dataset.tab);go(b.dataset.tab,false);});
  $('#view').addEventListener('click',e=>{const a=e.target.closest('[data-duel],[data-edition],[data-match],[data-nation],[data-player],[data-tourn],[data-year],[data-tab]');if(!a)return;if(a.tagName==='A')e.preventDefault();
    if(a.dataset.tab){clear(a.dataset.tab);go(a.dataset.tab,false);return;}
    if(a.dataset.duel){const [x,y]=a.dataset.duel.split('|');state.duelBy='p';state.dA=x;state.dB=y;go('duel',false);return;}
    if(a.dataset.edition&&EDS[a.dataset.edition]){openEdition(a.dataset.edition,false,a.dataset.match||null);return;}
    if(a.dataset.match&&state.tab==='draw'){state.match=a.dataset.match;render();return;}
    if(a.dataset.year){const y=+a.dataset.year;if(!byYear[y])return;ensureYearInLens(y);state.whole=false;state.year=y;state.edition=null;state.match=null;fillSeasons();applyTheme();drawRiver();go('season',false);return;}
    if(a.dataset.nation){state.nation=a.dataset.nation;go('nations',false);return;}
    if(a.dataset.player){state.player=a.dataset.player;go('players',false);return;}
    if(a.dataset.tourn){state.tourn=a.dataset.tourn;go('tournaments',false);return;}});
  addEventListener('resize',()=>{clearTimeout(window.__rz);window.__rz=setTimeout(()=>{drawRiver();if(['season','duel'].includes(state.tab))render();},150);});
}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init):init();
